INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words) VALUES
(481,'작업증명','작업증명(Proof-of-Work)은 제3자로부터의 서비스 요청(request)이 악의적인 공격 (spam 또는 DoS, Denial of Service)이 아님을 증명하기 위해서, 자원이…','작업증명(Proof-of-Work)은 제3자로부터의 서비스 요청(request)이 악의적인 공격 (spam 또는 DoS, Denial of Service)이 아님을 증명하기 위해서, 자원이 소모되는 작업을 추가로 수행할 것을 요구하는 것을 의미한다. 대표적인 작업증명으로는 웹사이트 로 그인시 특정한 문자 및 그림을 읽고 입력할 것을 요구하는 캡차를 들 수 있다. 작업증명의 특징은 비대칭성인데, 서비스 요청자가 수행하는 데는 어느 정도 자원이 소모되지만 이를 확인하기는 매우 쉬워야 한다. 작업증명은 가상자산인 비트코인 등을 채굴하는 합의 과정에 활용되고 있다.','','ㅈㅇㅈㅁ',ARRAY['비트코인']::text[]),
(482,'잠재GDP성장률','잠재GDP성장률은 노동이나 자본 등의 자원을 최대로 활용하였을 때 유지되는 실질GDP 의 증가율로서 한 나라 경제의 최대성장능력을 의미한다.','잠재GDP성장률은 노동이나 자본 등의 자원을 최대로 활용하였을 때 유지되는 실질GDP 의 증가율로서 한 나라 경제의 최대성장능력을 의미한다. 잠재GDP는 일정한 잣대로 추계할 수 없는 추상적인 개념이어서, 추정에 사용되는 원칙이나 통계분석기법 등에 따라 결과가 상이하다는 한계가 있다. 한편 잠재GDP는 성장률도 의미가 있지만 그 수준이 실제GDP보다 얼마나 높은가 또는 낮은가를 살피는 것도 매우 중요하다. 실제GDP 성장률이 잠재GDP성장률을 상회하더라도 그 수준은 잠재GDP를 하회할 수도 있다. 장기침체또한 우리나라와 같이 대외의존도가 매우 높은 경우에는 정의에 의한 생산요소의 완전고 용으로 규정하기에는 어려움이 있다. 그럼에도 잠재GDP성장률은 경제의 적정성장목표를 설정하는 데 유용하여 거시경제정책을 수립하고 시행하는 데 있어 널리 활용되고 있다.','','ㅈㅈㅅㅈㄹ',ARRAY['GDP갭']::text[]),
(483,'잠재경제활동인구','취업자도 아니고 실업자도 아닌 상태로 인해 비경제활동인구로 분류되었지만 취업 가능성과 의사 등을 고려하여 잠재적인 측면에서 경제활동인구로 간주되는 잠재취업가능자와 잠재구직자를 합한 개념이다.','취업자도 아니고 실업자도 아닌 상태로 인해 비경제활동인구로 분류되었지만 취업 가능성과 의사 등을 고려하여 잠재적인 측면에서 경제활동인구로 간주되는 잠재취업가능자와 잠재구직자를 합한 개념이다. 잠재취업가능자는 비경제활동인구 중에서 지난 4주간 구직활동을 하였으나 조사대상주간에 취업이 가능하지 않은 자를 가리킨다. 아울러 잠재구직자는 비경제활동인구 중에서 지난 4주간 구직활동을 하지 않았지만 조사대상주간에 취업을 희망하고 취업이 가능한 자를 말한다.','','ㅈㅈㄱㅈㅎㄷㅇㄱ',ARRAY['경제활동인구/비경제활동인구/경제활동참가율']::text[]),
(484,'장기금융시장(자본시장)','금융시장은 거래 금융상품의 만기를 기준으로 단기금융시장(Money Market)과 자본시장 (Capital Market)으로 구분되는데 자본시장은 만기 1년 이상의 장기채권이나 만기가 없는 주식이…','금융시장은 거래 금융상품의 만기를 기준으로 단기금융시장(Money Market)과 자본시장 (Capital Market)으로 구분되는데 자본시장은 만기 1년 이상의 장기채권이나 만기가 없는 주식이 거래되는 시장을 말한다. 자본시장은 주로 기업, 정부 등 자금 부족부문이 자금잉여부문으로부터 장기적으로 필요한 자금을 조달하는 데 활용되고 있어 장기금융시장이 라고 부른다. 우리나라의 자본시장에는 주식이 거래되는 주식시장과 국채, 회사채 및 금융채 등이 거래되는 채권시장이 있다.','','ㅈㄱㄱㅇㅅㅈ(ㅈㅂㅅㅈ)',ARRAY['단기금융시장']::text[]),
(485,'장기침체','장기침체(Secular Stagnation)는 1938년 Hansen이 기술 정체와 인구증가율 둔화에 따른 투자기회의 대폭 축소로 미국경제가 1930년대 대공황 발생 이후에도 회복되지 못하고 과소…','장기침체(Secular Stagnation)는 1938년 Hansen이 기술 정체와 인구증가율 둔화에 따른 투자기회의 대폭 축소로 미국경제가 1930년대 대공황 발생 이후에도 회복되지 못하고 과소 투자 및 총수요 부족에 직면할 것으로 예측하면서 처음 사용한 용어로 알려져 있으며, 최근에는 하버드대학의 Summers 교수가 IMF경제포럼(2013.11) 연설에서 “선진국 경제는 2000년대 초부터 구조적 요인에 의해 장기침체에 진입하였다”고 주장하면서 널리 회자되고 있다. 장기침체란 경제활동의 장기적 침체라는 뜻으로 대체로 실제GDP가 잠재GDP를 하회하는 가운데 총수요가 억제 되어 있거나 공급측면에서 잠재GDP가 정체되어 있는 상황으로 정의된다. 여기서 장기는 인구고령화 등에 따른 노동증가율 감소, 혁신 정체, 자본투자 감소 등 공급요인에 의해 성장잠재력이 축소되는 현상과 연관이 있다. 그리고 침체는 디레버리징 등 기초경제여건의 변화, 소득불평등 심화, 재정지출 축소, 글로벌 금융위기 이후 위험회피성향의 증가 등 수요요인에 의해 성장회복이 지연되거나 성장이 정체되는 것으로 경기순환과 관련이 있다. 장기침체란 용어 자체가 수요요인(경기순환)과 공급요인(성장잠재력)이 혼재되어 있기 때문에 장기침체 여부와 그 원인에 대해서 는 다양한 시각이 존재한다.','','ㅈㄱㅊㅊ',ARRAY['경기조절정책/경제안정화정책','골디락스경제','대안정기']::text[]),
(486,'장내시장','장내시장이란 주식과 같은 유가증권이나 금융상품 등이 표준화된 거래방식에 따라 거래가 이루어지는 조직화된 시장을 말한다.','장내시장이란 주식과 같은 유가증권이나 금융상품 등이 표준화된 거래방식에 따라 거래가 이루어지는 조직화된 시장을 말한다. 한국거래소가 운영하는 유가증권시장이나 코스닥시장이 대표적인 장내시장이다. 장내시장은 대표적인 유통시장(secondary market)인데 이미 발행된 유가증권의 시장성과 환금성을 높여주고 자유로운 경쟁을 통해 공정한 가 격을 형성하는 기능을 한다. 주식이 유가증권시장이나 코스닥시장에서 거래가 되기 위해서는 상장이 되어야 하는데 이를 위해서는 해당 기업이 영업활동기간, 규모, 주식분산, 경영성과 등과 관련하여 일정한 요건을 충족해야 한다. 채권의 경우 최근에 발행된 국고채 (on-the-run)가 대표적인 채권 장내시장인 국채전문유통시장에서 거래가 이루어진다. 한편 소액 국공채(액면 5천만원 미만)는 환금성 제고를 위해, 전환사채는 수요기반 확충을 위해 장내거래가 의무화되어 있다. 이런 거래를 제외한 일반적인 채권, 단기금융상품및 파생상품 등은 대부분 장외시장에서 거래된다.','','ㅈㄴㅅㅈ',ARRAY['장외시장']::text[]),
(487,'장단기금리차','장단기금리차장단기금리차란 일정 시점에서 장기금리와 단기금리의 차이를 의미한다.','장단기금리차장단기금리차란 일정 시점에서 장기금리와 단기금리의 차이를 의미한다. 장단기금리차는 다양한 만기의 지표금리를 이용해서 산출할 수 있다. 예를 들어 어떤 시점에서 국고 채금리(3년 만기)가 2.0%이고 한국은행 정책금리가 1.5%라면 여기서 장단기금리차는 0.5%p(2.0%-1.5%)이다. 또는 10년만기 국고채금리와 3년만기 국고채금리의 차이도 또하나의 장단기금리차로 이해할 수 있다. 여기서의 장단기는 통상 1년을 기준으로 하기 보다는 비교하려는 만기의 상대성에 달려있다. 즉 후자의 예에서 10년을 장기로 보는 경우 3년은 단기의 의미로 비교된 것이다. 장단기금리차는 시장이 경제를 어떻게 바라보고 있는지를 판단하는데 유용한 지표로 활용된다. 장단기금리차가 줄어들고 있다면(정책금리는 한국은행이 결정하기 때문에 새로운 정책금리 결정이 나오기 전까지는 변함이 없는 반면 장기금리는 하락) 이는 경제성장률이 떨어지고 실업률이 상승하는 등 향후 경제가 더나빠질 것으로 시장이 기대한다고 볼 수 있다. 특히 이런 상황에서 경기진작을 위해 한국은행이 정책금리를 인하할 것이라는 기대가 강화되는 경우에는 이런 현상이 더욱 두드러진다. 시장이 정책금리 인하를 극단적으로 기대하는 경우에는 3년 국고채금리가 한국은 행 정책금리를 하회하는 현상도 발생한다. 이를 장단기금리 역전이라고 한다. 반대로 장 ㅈ 단기금리차가 확대되고 있다면 향후 경제가 좋아질 것이라고 시장이 기대한다고 볼 수 있다. 특히 경제성장률이 잠재성장률에 근접하고 있어 한국은행이 정책금리를 인상할 것이 라는 기대가 형성되는 경우 그 차이는 더욱 확대된다. 또한 장단기금리차는 채권의 수급에 의해서도 영향을 받는다. 장기채권에 대한 수요가 많아지면 장기금리가 하락하여 장단기금리차가 축소되고 장기채권의 공급이 많아지면 장기금리가 상승하여 장단기금리차가 확대된다. 장단기금리차의 변화는 수익률곡선의 형태가 가팔라지거나(steepening) 평탄해지는(flattening) 것으로 표현되기도 한다. 수익률곡선이 가팔라진다는 것은 장단기금리차가 확대되는 것을 의미하고 수익률곡선이 평탄해진다는 것은 장단기금리차가 축소되는 것을 의미한다.','','ㅈㄷㄱㄱㄹㅊ',ARRAY['기준금리']::text[]),
(488,'장외시장','장외시장(OTC; Over-The-Counter)이란 장내시장이 아닌 시장에서 중개기관을 통해 개별적으로 거래가 이루어지는 시장을 말한다.','장외시장(OTC; Over-The-Counter)이란 장내시장이 아닌 시장에서 중개기관을 통해 개별적으로 거래가 이루어지는 시장을 말한다. 장내시장에서 거래가 되기 위해서는 금융상품이 표준화되어야 하는데 채권이나 단기금융상품 또는 파생상품은 표준화하기 어렵다. 예를 들어 채권은 국채, 지방채, 특수채, 금융채, 회사채, 자산유동화증권 등 종류도 많은 데다 발행(잔존) 만기, 발행금리 및 신용도 등이 다르기 때문에 현실적으로 표준화하기 어렵다. 콜, 기업어음 등 단기금융상품이나 파생상품도 다양한 발행(잔존) 만기, 다양한 표면금리, 상이한 신용도 등으로 인해 표준화하기 곤란하다. 이처럼 표준화가 어려운 금융상품들은 장내거래를 하지 못하고 불가피하게 장외시장에서 거래가 이루어지게 된다. 장외거래는 보통 중개회사가 전화, 인터넷 메신저 등을 통해 매도 또는 매수를 원하는 투자자의 호가를 받은 후 반대거래를 원하는 상대방을 찾아 거래를 성사시킨다. 따라서 장내거래와는 달리 장외거래가 활성화되기 위해서는 중개기관의 역할이 매우 중요하다.','','ㅈㅇㅅㅈ',ARRAY['장내시장']::text[]),
(489,'재산소득','국민계정에서 재산소득(Property Income)이란 금융자산 또는 자연자원(주로 토지 및 지하자원)의 소유주가 타 경제주체에게 자금을 공급하거나 유형 비생산자산을 사용하도록하고 그 대가로서…','국민계정에서 재산소득(Property Income)이란 금융자산 또는 자연자원(주로 토지 및 지하자원)의 소유주가 타 경제주체에게 자금을 공급하거나 유형 비생산자산을 사용하도록하고 그 대가로서 수취하는 소득을 말한다. 금융자산은 이자, 배당 등 투자소득의 형태로, 자연자원은 임료의 형태로 재산소득이 발생한다. 이를 구체적으로 살펴보면, 재산소득은 이자, 배당 및 준법인기업소득인출, 국외직접투자에 대한 재투자수익, 투자소득지급, 임 료 등으로 분류된다. 이자는 예금, 채무증권, 대출 및 기타 수취권 등 금융자산의 소유주가 위에 자금을 공급하거나 유형 비생산자산을 사용하도록 하고 그 대가로서 수취하는 소득을 말한다. 배당은 주주가 법인기업으로부터 자금 공여의 대가로 취득하게 되는 소득이 다. 준법인기업소득인출은 소유주가 기업에 자금을 투자함으로써 발생하는 소유주의 소득이다. 국외직접투자에 대한 재투자수익은 거주자의 해외직접투자 또는 비거주자의 국내직접투자에서 발생한 이익이 배당 등의 형태로 실제로 배분되고 남은 유보이익을 의제하여 투자자에게 지급 처리한 것을 말한다. 투자소득지급은 보험가입자의 법적준비금 및재정정책연금자산 등의 운용에서 수취하는 투자소득을 해당 자산의 실제 소유자에게 지급된 것으로 의제처리 한 소득이다. 임료는 토지, 지하자원 등 자연자원 사용에 대한 재산소득으로, 현재 우리나라는 토지에 대한 임료만을 계상하고 있다.','','ㅈㅅㅅㄷ',ARRAY['본원소득']::text[]),
(490,'재정수지','정부의 수입과 지출의 차이를 재정수지라고 한다.','정부의 수입과 지출의 차이를 재정수지라고 한다. 수입과 지출이 같으면 균형, 수입이 더많으면 흑자, 지출이 더 많으면 적자라고 한다. 재정적자가 발생하면 국채발행이나 차입이 늘어나 정부부채가 증가하게 된다. 정부의 재정활동은 조세와 정부지출의 형태로 가계의 소비와 기업의 투자라는 거시경제의 순환에 영향을 주게 된다. 재정지출로 정부서비스가 생산되지만 일정 부문은 조세 등으로 조달된 자금이 타 부문으로 이전되는 성격도 갖고 있다. 그래서 재정적자가 과다하지 않도록 유로존(EU)은 안정성장 협약에 의거 회원국들의 재정적자를 GDP의 3% 이내, 장기적인 정부부채는 GDP의 20%를 넘지 않도록 관리하고 있다. 한편 우리나라는 당해 연도의 총수입에서 총지출을 뺀 것을 “통합재정수지” ㅈ 라고 지칭하고, 통합재정수지에서 국민연금기금, 사립학교교직원연금기금, 산업재해보상보험및예방기금 등 사회보장성 기금의 수지를 제외한 재정수지를 별도로 “관리재정수지” 라고 별도로 산출 운용하고 있다. 이는 사회보장성 기금수입은 장기적인 미래지출을 위한 것으로 당해 연도의 재정활동 결과로 보기 곤란하며 기금의 성숙도에 따라 대규모 흑자나 적자가 발생하여 당해 연도의 재정활동을 판단하는데 효과적이지 않을 수 있기 때문이다.','','ㅈㅈㅅㅈ',ARRAY['국채']::text[]),
(491,'재정정책','정부의 지출과 조세를 정책수단으로 사용하는 정부의 제반 정책을 일컬어 재정정책이라고 한다.','정부의 지출과 조세를 정책수단으로 사용하는 정부의 제반 정책을 일컬어 재정정책이라고 한다. 재정정책의 목표는 일반적으로 완전고용, 물가안정, 국제수지 균형, 경제성장, 소득재분배 등이 있다. 그러나 좁은 의미 또는 단기적으로는 정부지출과 조세수입의 양과 구조를 의도적으로 변화시켜 총수요를 조절함으로써 경제안정을 도모하려는 확장적 혹은 긴축적 재정활동만을 재정정책이라 한다. 예를 들어 단기적으로 불황이 발생할 경우정부지출을 늘려 경기를 진작할 수 있다. 또한 기업의 연구개발 지출에 보조금을 지급하면 기술개발이 촉진돼 장기적으로 경제성장률이 확대될 수 있다.','','ㅈㅈㅈㅊ',ARRAY['경기조절정책/경제안정화정책','통화정책']::text[]),
(492,'재정환율','자국 통화와 다른 외국 통화가 국내외환시장에서 직접적으로 거래되지 않는 경우 각각의 시장에서 결정되는 가격을 이용해 산출하는 환율을 말한다.','자국 통화와 다른 외국 통화가 국내외환시장에서 직접적으로 거래되지 않는 경우 각각의 시장에서 결정되는 가격을 이용해 산출하는 환율을 말한다. 예를 들면 일본 엔화와 원화를 교환할 수 있는 시장이 없으므로 원/엔 환율은 서울 외환시장에서 결정된 원/달러 환율과 도쿄 외환시장에서 형성된 엔/달러 환율을 이용하여 산출한다. 만약 원/달러 환율이 1,100원이고, 엔/달러 환율이 달러당 110엔이라면 재정환율인 원/엔 환율은 100엔당 1,000원이 된다. 이처럼 재정환율을 사용하는 이유는 세계적으로 각국 외환시장에서의 거래가 대부분 미 달러화를 중심으로 이루어지고 있어 기타 통화 간 외환시장은 발달되어있지 않기 때문이다. 2025년 6월 현재 우리나라는 서울외국환중개회사가 서울 외환시장에서 결정되는 원/달러, 원/위안 환율과 국제금융시장에서 형성된 미 달러화와 다른 통화간 환율(크로스 레이트)을 매개로 하여 55개 통화에 대한 재정환율을 매일 고시하고 있다.','','ㅈㅈㅎㅇ',ARRAY['BIS 자기자본비율','경영실태평가/은행경영실태 평가등급제도']::text[]),
(493,'전방연쇄효과','전방연쇄효과란 특정 산업에서 제품의 생산이 증가할 때 동 생산품을 중간재나 원재료로 사용하는 산업에 미치는 경제적 파급 효과를 말한다.','전방연쇄효과란 특정 산업에서 제품의 생산이 증가할 때 동 생산품을 중간재나 원재료로 사용하는 산업에 미치는 경제적 파급 효과를 말한다. 특정 산업의 생산이 증가하면, 동 산업의 생산품을 중간재로 활용하는 다른 산업들의 생산비용이 낮아지거나 공급이 원활해지면서 이들 산업의 생산과 부가가치 창출에도 긍정적인 영향을 줄 수 있다. 전방연쇄효과는 산업연관분석(Input-Output Analysis)에서 중요한 개념 중 하나로, 특정 산업이 공급 측면에서 경제 전체에 얼마나 영향을 미치는지를 보여준다. 예를 들어, 석유화학 산업은 플라스틱, 섬유, 자동차 등 다양한 산업에 원재료를 제공하는데, 석유화학 산업의 생산증가가 다른 산업의 생산 확대를 유발하는 작용이 바로 전방연쇄효과이다.','','ㅈㅂㅇㅅㅎㄱ',ARRAY['생산유발효과','후방연쇄효과']::text[]),
(494,'전산업생산지수','우리나라 경제전체의 모든 산업을 대상으로 재화와 용역에 대한 생산활동의 흐름과 변화를 월별지수로 나타낸 것이다.','우리나라 경제전체의 모든 산업을 대상으로 재화와 용역에 대한 생산활동의 흐름과 변화를 월별지수로 나타낸 것이다. 모든 재화와 용역의 생산수준을 한 눈에 볼 수 있는 종합지표로 업종별로 생산증감의 방향이 다를 때 전체산업의 방향 파악가능하다. 전산업생산지수는 광공업생산지수와 서비스업생산지수로 구분할 수 있으며, 광공업생산지수는 광업, 제조업, 전기·가스업을 대상으로 일정 기간 중에 이루어진 산업생산활동의 수준을 나 타내는 지표이며 서비스업생산지수는 한국표준분류상의 서비스업에 해당되는 13개 산업의 생산활동을 종합적으로 파악하기 위한 것으로 개별업종의 상대적 중요도인 부가가치기준 가중치를 적용하여 지수화한 것이다. 생산지수는 전체 경기의 흐름과 거의 유사하게움직이는 대표적인 경기동행지표이다. 또한 동 지수들은 GDP 통계의 추계를 위한 기초자료로 사용되며, 생산활동의 수준을 파악할 때 GDP와 함께 핵심적인 지표로 사용되고 있다.','','ㅈㅅㅇㅅㅅㅈㅅ',ARRAY['동행종합지수','제조업생산능력/가동률지수']::text[]),
(495,'전세가율','전세가율은 주택매매가격 대비 전세가격(전세보증금)의 비율을 의미하는데, 예를 들어 매매가격이 10억원이고 전세가격이 6억원이라면 전세가율은 60%이다.','전세가율은 주택매매가격 대비 전세가격(전세보증금)의 비율을 의미하는데, 예를 들어 매매가격이 10억원이고 전세가격이 6억원이라면 전세가율은 60%이다. 전세가율은 일반적으로 임차인의 전세(보증)금 반환 안정성을 판단하는 지표로 사용되는데, 전세가율이 높을수록 주택가격의 하락시 전세금 반환 리스크가 커질 수 있기 때문이다. 전세가율이 높은 상황에서 주택가격이 하락하여 매매가격이 기존 전세금보다 낮아지면 임대인이 해당주택을 매도해도 전세금을 돌려줄 수 없는 상황(깡통전세)이 발생할 수 있다. 한편 전세가 율은 주택매매가격의 변동 추세를 파악하는 선행지표로 사용되기도 하는데, 이는 전세가 율이 상승할 경우 갭투자(전세보증금을 활용하여 적은 돈으로 주택을 매입하는 투자방식) 유인이 확대됨으로써 주택매매가격의 상승 압력으로 작용하기 때문이다.','','ㅈㅅㄱㅇ',ARRAY['역전세']::text[]),
(496,'전월세 전환율','전월세 전환율이란 전세보증금을 월세로 전환할 때 적용되는 비율로, 임대인은 요구수익률, 임차인은 전월세 선택 및 월세 계약시 기회비용을 계산하는 지표로 활용되고 있다.','전월세 전환율이란 전세보증금을 월세로 전환할 때 적용되는 비율로, 임대인은 요구수익률, 임차인은 전월세 선택 및 월세 계약시 기회비용을 계산하는 지표로 활용되고 있다. 전월세 전환율은 “{월세/(전세보증금-월세보증금)}×100”으로 산정된 월세 이율을 연이율로 환산(월세이율×12)하여 산정한다. 예를 들어 전세보증금 1억원의 주택을 월세보증금 1천만원과 월세 50만원의 계약으로 바꿀 경우 전월세 전환율은 6.7%로 계산된다(월세이 율 0.55%=50만원/(1억원-1천만원)×12). 동일 단지·면적이 유사한 월세 매물중 전월세전환율이 높은 것은 월세 부담이 상대적으로 크다는 것을 의미한다. 최근에는 전세 사기에 대한 우려, 전세대출 규제 강화 등의 영향으로 월세 수요가 늘어나면서 전월세 전환율이 상승세를 나타내고 있다.','','ㅈㅇㅅㅈㅎㅇ','{}'::text[]),
(497,'전자금융','금융업무에 컴퓨터 및 정보통신기술을 적용하여 자동화 및 전자화(Network 화)를 구현하는 것을 말한다.','금융업무에 컴퓨터 및 정보통신기술을 적용하여 자동화 및 전자화(Network 화)를 구현하는 것을 말한다. 국내의 전자금융거래법에서는 이러한 전자금융거래를 ‘금융회사또는 전자금융업자가 전자적 장치를 통하여 금융상품 및 서비스를 제공하고, 이용자가 전자단기사채금융회사 또는 전자금융업자의 종사자와 직접 대면하거나 의사소통을 하지 아니하고 자동화된 방식으로 서비스를 이용하는 거래’로 정의하고 있다. 전자금융의 수단으로는 홈뱅킹, 펌뱅킹 등의 PC뱅킹과 전화기를 이용한 폰뱅킹이 주로 이용되었으나, 정보처리 기술및 통신기술을 활용한 각종 전자금융서비스의 개발이 이루어짐으로써 시간적·공간적 제약 없이 금융서비스를 이용할 수 있게 되었다. 최근에는 스마트폰의 등장과 함께 다양한 직불 및 선불 전자지급수단이 출시되고 금융기관을 중심으로 모바일금융서비스 제공이 확산되고 있다. 특히 금융과 IT기술의 융합이 가속화되면서 출현한 금융서비스는 기존 금융기관이 아닌 IT업체들의 전자금융산업 참여를 가능하게 하였으며, 금융과 기술의 융합인 핀테크(Fintech)가 등장하는 등 관련 산업환경이 변화하면서 비금융기업들의 참여가 더욱 활발하게 진행될 것으로 예상된다.','','ㅈㅈㄱㅇ',ARRAY['금융EDI','핀테크']::text[]),
(498,'전자금융공동망','전자금융공동망은 ARS공동망을 확대 개편하여 2001년 4월부터 가동된 시스템으로 인터 ㅈ 넷뱅킹, 모바일뱅킹 등 전자금융서비스에 대한 중계업무를 처리하고 있다.','전자금융공동망은 ARS공동망을 확대 개편하여 2001년 4월부터 가동된 시스템으로 인터 ㅈ 넷뱅킹, 모바일뱅킹 등 전자금융서비스에 대한 중계업무를 처리하고 있다. 전자금융공동망의 대상 업무는 유·무선전화, PC 등의 매체를 통해 이루어지는데 크게 대고객업무와 중계업무로 구분된다. 대고객업무는 예금잔액 및 신용카드 관련 각종 정보조회업무, 수표의 사고유무 조회 및 환율조회 등이며, 중계업무에는 타행이체, 타행이체 거래확인 조회 및자기앞수표 조회 업무 등이 있다. 전자금융공동망을 이용할 수 있는 예금계좌에는 보통예금, 당좌예금, 저축예금, 기업자유예금, 투자자예탁금 등이 있다. 은행의 전자금융업무 운영시간은 연중무휴로 00시 05분부터 23시 55분까지로 하되, 공동운영시간대인 07시부터 23시 30분 이외 시간대의 운영여부는 참가기관이 자율적으로 정하고 있다.','','ㅈㅈㄱㅇㄱㄷㅁ',ARRAY['소액지급시스템']::text[]),
(499,'전자단기사채','전자단기사채란 자본시장법상의 채무증권으로서 실물이 아닌 전자적으로 발행·유통되는 단기금융상품을 말한다.','전자단기사채란 자본시장법상의 채무증권으로서 실물이 아닌 전자적으로 발행·유통되는 단기금융상품을 말한다. 전자단기사채의 법적 성격은 어음은 아니지만 경제적 실익은 기존의 기업어음과 동일하다. 다만, 기업어음은 실물로 발행·유통되나 전자단기사채는 실물없이 중앙등록기관의 전자장부에 등록하는 방식으로 발행·유통되는 점이 다르다. 전자단기사채는 어음이 갖는 문제점, 즉 공시의무가 없어 시장의 투명성과 투자자 보호 장치가 미흡한 점, 위·변조, 분실 등 실물발행에 따른 위험 등을 개선하고, 등록기관의 전자장부에 등록하는 방식으로 발행·유통됨에 따라 거래의 투명성을 높이는 한편 증권사 등 비은행금융기관이 다양한 단기자금 조달 및 운용수단을 갖도록 하여 단기금융시장의 리스크가 콜시장으로 집중되는 것을 방지하기 위해 2013년 1월에 도입되었다. 전자단기사채로 인정받기 위해서는 ① 금액은 1억원 이상 ② 만기는 1년 이내 ③ 사채금액은 일시 납입 ④ 만기에 전액 일시 상환 ⑤ 주식관련 권리부여 금지 ⑥ 담보설정 금지 등 여섯 가지 요건을 갖추어야 한다. 만기를 1년 이내로 제한한 것은 회사채시장과의 경합 가능성을 최소화하기 위해서다. 전자단기사채의 발행기관, 인수·매매기관 및 중개기관은 성격상 기업어음 시장과 거의 유사하다. 한편, 2019년 9월부터 전자증권법이 시행됨에 따라 기존에 쓰이 던 명칭인 ‘전자단기사채’가 ‘단기사채’로 변경되었다.','','ㅈㅈㄷㄱㅅㅊ',ARRAY['기업어음(CP)']::text[]),
(500,'전자상거래','인터넷을 이용하여 가상공간에서 광고, 발주, 수주 등의 상거래 및 대금지급을 수행하는 것을 말한다.','인터넷을 이용하여 가상공간에서 광고, 발주, 수주 등의 상거래 및 대금지급을 수행하는 것을 말한다. 전자상거래(EC; Electronic Commerce)는 초기에 기업 간 거래가 대부분이었으나 인터넷의 보급 확산에 따라 일반 소비자를 대상으로 물품을 판매하거나 서비스를 제공하는 사이버 쇼핑 등이 많이 증가하고 있다. 또한 시간과 공간의 제약이 없고 유통비용 등 부대비용이 들지 않는다는 장점으로 인하여 실물거래에서부터 교육·의료·금융서 비스 분야 등으로 급속도로 확산되고 있다. 지급수단으로는 신용카드, 은행 계좌이체, 전자화폐 등이 이용되고 있다. 세계 각국은 전자상거래를 보다 활성화시키기 위해 인터넷을 통해 안전하게 지급할 수 있는 수단을 적극적으로 개발하고 있는데, VISA·Master Card 등에서 전자상거래의 안전성을 확보할 수 있는 SET(Secure Electronic Transaction)이 라는 전자상거래 S/W를 공동으로 개발한 것이 그 예이다.','','ㅈㅈㅅㄱㄹ',ARRAY['전자서명','전자화폐']::text[]),
(501,'전자서명','전자서명은 수기서명의 전자적인 대체물로서 전자 문서의 진정성 및 작성자의 신원을 확인할 수 있도록 암호화한 정보를 말한다.','전자서명은 수기서명의 전자적인 대체물로서 전자 문서의 진정성 및 작성자의 신원을 확인할 수 있도록 암호화한 정보를 말한다. 광의의 전자서명에는 수기서명을 스캐닝한 이미지, 접근제어를 위한 비밀번호 등이 있으나 「전자서명법」에 의한 전자서명은 공개키 암호방식에 의한 디지털 서명만을 의미하고 있다. 특히 「전자서명법」에 따라 공신력과 인증시스템을 갖추어 지정받은 공인인증기관에 의해 발급된 전자서명을 공인인증서라고 하며 각종 금융거래 및 전자정부 서비스 이용 시 보편적으로 사용되고 있다. 우리나라의 공인인증기관으로는 금융결제원, 코스콤, 한국정보인증, 한국전자인증, 한국무역정보통신 등 5개 기관이 있으며, 각 기관별로 전문서비스 영역이 특화되어 있다.','','ㅈㅈㅅㅁ',ARRAY['전자상거래','전자금융']::text[]),
(502,'전자어음','전자어음은 실물어음이 아닌 전자적 형태로 발행된 어음으로 발행인, 수취인, 금액 등 어음 정보를 전자문서 형태로 작성하며 전자어음 관리기관(금융결제원)의 전산시스템에 등 록된 약속어음이다.','전자어음은 실물어음이 아닌 전자적 형태로 발행된 어음으로 발행인, 수취인, 금액 등 어음 정보를 전자문서 형태로 작성하며 전자어음 관리기관(금융결제원)의 전산시스템에 등 록된 약속어음이다. 따라서 전자어음은 발행, 배서, 권리행사, 소멸 등 모든 단계가 온라인에서 전자적인 방법으로 처리되나 법적인 효력은 실물 약속어음과 동일하다. 전자어음 은 어음 거래의 투명화, 분실·도난 등 사고 예방, 어음 유통과 관리비용을 절감하고 어음 제도의 폐해를 보완하기 위한 것으로, 2005년 9월부터 「전자어음의 발행 및 유통에 관한 법률」(약칭 「전자어음법」)에 근거하여 전자 지급수단으로 사용되고 있다. 실물어음과 다 른 전자어음만의 특징으로는 백지어음 발행 및 배서 불가능, 환어음 발행 불가능, 만기일은 발행일로부터 1년까지 가능, 배서 횟수는 20회로 제한, 지급지는 금융기관(은행)으로 한정 등이 있다. 한편 정부의 약속어음제도 폐지 추진에 따라 2016년중에 「전자어음법」 이 개정되어 2018년 5월 30일부터 3년 이내에 전자어음의 만기가 6개월에서 3개월로 단계적으로 축소됨으로써 2021년 5월 30일부터 3개월이 적용되고 있다.','','ㅈㅈㅇㅇ',ARRAY['지급수단']::text[]),
(503,'전자정보교환제도','금융기관 수납장표의 전자정보교환제도(Truncation)란 공과금 납부용지, 지로용지, 어음, 수표 등 금융기관에서 수납하는 각종 장표를 표준화하고 전산화하여 장표 실물의 이 동 없이 전산망을…','금융기관 수납장표의 전자정보교환제도(Truncation)란 공과금 납부용지, 지로용지, 어음, 수표 등 금융기관에서 수납하는 각종 장표를 표준화하고 전산화하여 장표 실물의 이 동 없이 전산망을 통한 정보(전산데이터)의 이동만으로 교환 업무를 처리하는 제도이다. 이를 통해 장표의 실물 이동 및 수작업에 따른 인적·물적 비용, 분실, 도난 등 사고 발생및 오류발생 가능성을 크게 감소시키게 되었다. 수납장표 전자정보교환제도는 2000년 5 월 자기앞수표를 시작으로 대상 장표의 범위를 확대하여 2009~2010년중 어음 및 기타수표의 교환이 정보화되면서 마무리되었다. 이에 따라 현재 금융결제원은 어음, 수표 및장표지로의 교환업무를 모두 전자정보교환방식으로 수행하고 있다.','','ㅈㅈㅈㅂㄱㅎㅈㄷ',ARRAY['어음교환','전자어음']::text[]),
(504,'전자지급결제대행(PG)','전자지급결제대행(PG; Payment Gateway)이란 인터넷 쇼핑몰 등의 전자상거래에서 구매자로부터 대금을 수취하여 판매자에게 지급될 수 있도록 지급정보를 송·수신하는 것 또는 그 대가의…','전자지급결제대행(PG; Payment Gateway)이란 인터넷 쇼핑몰 등의 전자상거래에서 구매자로부터 대금을 수취하여 판매자에게 지급될 수 있도록 지급정보를 송·수신하는 것 또는 그 대가의 정산을 대행하거나 매개하는 것을 의미한다. 가령 구매자가 인터넷 쇼핑몰에 서 신용카드로 대금을 지급하는 경우 신용카드 PG업자는 해당 쇼핑몰(가맹점)을 대신하여신용카드사에 거래내역 및 승인정보 등 지급정보를 전송하고 신용카드사로부터 대금을 지급받아 일정 수수료를 공제한 후 가맹점에 지급하게 된다. 온라인상의 전자상거래 규모가 급속히 늘어남에 따라 PG업자는 IT업체가 중심이 되어 동 서비스를 제공하고 있다.','','ㅈㅈㅈㄱㄱㅈㄷㅎ()',ARRAY['지급결제시스템']::text[]),
(505,'전자화폐','IC카드 등에 화폐가치를 저장하였다가 상품 등의 구매에 사용할 수 있는 전자지급수단으로서 범용성과 환금성을 갖춘 것을 말한다.','IC카드 등에 화폐가치를 저장하였다가 상품 등의 구매에 사용할 수 있는 전자지급수단으로서 범용성과 환금성을 갖춘 것을 말한다. 전자화폐(Electronic Money)의 유형은 가치저장 매체에 따라 IC카드형과 네트워크형으로 구분할 수 있다. IC카드형은 플라스틱 카드 위에 부착된 IC칩에 화폐가치를 저장하였다가 상품이나 서비스를 구매한 후 가맹점용전환사채(CB) 단말기 등을 통하여 대금을 지급하는 형태의 전자화폐로 국내에는 K-Cash, VisaCash, MYbi 등이 있다. 인터넷 네트워크를 통하여 구매대금을 지급하는 형태의 네트워크형 전자화폐는 현재는 발행되지 않고 있다.','','ㅈㅈㅎㅍ',ARRAY['전자상거래','전자금융']::text[]),
(506,'전자화폐공동망','전자화폐공동망은 금융기관이 공동으로 개발한 한국형 전자화폐(K-CASH) 이용시 발생한 금융기관간 정산금액을 결제하기 위한 시스템으로 2000년 7월 가동되었다.','전자화폐공동망은 금융기관이 공동으로 개발한 한국형 전자화폐(K-CASH) 이용시 발생한 금융기관간 정산금액을 결제하기 위한 시스템으로 2000년 7월 가동되었다. K-CASH 이 용자가 본인의 예금을 기반으로 전자화폐에 가치를 저장하면, 발행은행은 고객의 예금계좌에서 전자화폐 구매금액을 인출하여 선불계정에 예치한다. 구매거래가 발생하여 금융결제원으로부터 지급 및 정산내역을 전송받으면, 결제할 금액을 선불계정에서 인출하여 한국은 행과의 차액결제를 통해 매입은행에 이체한다. 한편 2013년 3월 국내은행들과 금융결제원이 공동개발한 모바일지갑 서비스인 뱅크월렛(BankWallet)의 선불전자지급수단인 뱅크머니(BankMoney)도 전자화폐공동망을 이용하여 개인간 송금 서비스를 제공하고 있다. 전 ㅈ 자화폐 거래의 결제과정에는 발행은행, 매입은행, VAN사업자 및 전자화폐공동망센터(금융결제원)가 참여하고 있으며, 은행간 거래차액의 결제는 한은금융망을 통해 이루어진다.','','ㅈㅈㅎㅍㄱㄷㅁ',ARRAY['소액지급시스템','전자화폐']::text[]),
(507,'전환사채(CB)','전환사채(Convertible Bond)란 사채로 발행되었지만, 일정 기간이 지난 후 소유자의 청구에 의하여 발행회사의 주식(보통주)으로 전환할 수 있는 권리가 부여된 사채를 말한다.','전환사채(Convertible Bond)란 사채로 발행되었지만, 일정 기간이 지난 후 소유자의 청구에 의하여 발행회사의 주식(보통주)으로 전환할 수 있는 권리가 부여된 사채를 말한다. 처음 기업이 발행할 땐 보통의 회사채와 동일하지만 일정 기간이 지나 주식전환권이 행사되면 채권을 주식으로 바꿔 주가 상승의 이익을 취할 수 있다. 예를 들어 A기업이 1년 만 기 전환사채를 만기보장수익률 10%, 전환가격 10,000원으로 발행한다고 가정하자. 향후 주가가 11,000원 이상(11,000원 이하인 경우에는 채권으로 이자를 수취하는 것이 더유리함)이 되었다면 주식으로 전환해 시세 차익을 얻을 수 있고 주가가 11,000원 이하일 경우에는 만기까지 채권을 보유해 10%의 이자를 받으면 된다. 전환사채는 수익성이 기대되나 위험이 있어 투자자금 확보에 어려움을 겪는 기업, 채권과 주식의 장점을 모두취하려는 투자자에게 이용된다. 만기보장수익률은 보통의 회사채에 비해 낮은 편이어서 기업의 입장에서는 일반 회사채에 비해 낮은 비용으로 자금을 조달할 수 있다.','','ㅈㅎㅅㅊ()',ARRAY['신주인수권부사채(BW)']::text[]),
(508,'정규직/비정규직','정규직은 법적인 개념은 아니지만 기간이 정해져 있지 않은 고용형태로 근로자와 사업주가 직접 근로계약을 체결하고 전일제로 근무하면서 정년까지 보장된다는 의미로 받아들이고 있다.','정규직은 법적인 개념은 아니지만 기간이 정해져 있지 않은 고용형태로 근로자와 사업주가 직접 근로계약을 체결하고 전일제로 근무하면서 정년까지 보장된다는 의미로 받아들이고 있다. 따라서 회사가 소멸되지 않는 한 원할 때까지 계속 근무가 가능하며 임금, 휴가, 상여금 등의 각종 복지혜택도 받을 수 있다. 반면 비정규직은 근로기간이 정해져 있는 계약직과 일용직, 파견 도급직, 상시 근로를 하지 않는 시간제 근로자 등을 포함하는 개념으로 계약기간이 종료되는 시점이 정해져 있다. 인턴은 일정기간 근무시켜 능력과 성품등을 평가하여 필요시 채용하는 방식이다. 계약직은 일반계약직과 무기계약직으로 구분할 수 있다. 우선 일반계약직은 회사와 근로자가 정해진 한정된 기간에 근로계약을 맺은 것으로 정년이 보장되지 않기 때문에 정규직보다 불안정하고 임금 및 근무환경이 열악하다. 무기계약직은 일반계약직과는 달리 계약기간을 정하지 않은 것이지만 임금 및 복지나 승진 등에 대해서는 일반계약직과 비슷하다. 파견직은 아웃소싱 업체에 고용되어 있으면서 다른 업체로 파견되어 일하는 근로자를 말한다. 파견기간이 2년이 넘게 되면 파견 나 간 다른 업체에서 직접 고용해야 할 의무가 생긴다.','','ㅈㄱㅈ/ㅂㅈㄱㅈ',ARRAY['한시적 근로자']::text[]),
(509,'정보의 비대칭성','시장에서 거래의 당사자인 쌍방 간의 상호작용에 필요한 정보량에 차이가 있는 경우를 말한다.','시장에서 거래의 당사자인 쌍방 간의 상호작용에 필요한 정보량에 차이가 있는 경우를 말한다. 이러한 정보의 비대칭성(Information Asymmetry)은 효율적인 자원배분을 불가 능하게 하며 역선택(adverse selection)이나 도덕적 해이(moral hazard) 등의 문제를 낳는다. 역선택은 중고차시장의 경우와 같이 판매자가 파는 물건의 속성에 대해 구매자보다 정보가 많을 때 생기는데 이런 상황에서는 판매자가 구매자에게 품질이 낮은 물건을','','ㅈㅂㅇㅂㄷㅊㅅ','{}'::text[]),
(510,'정부당좌예금계정','시장에 아예 내놓지 않게 되거나, 구매자가 좋지 않은 물건을 비싸게 사게 된다.','시장에 아예 내놓지 않게 되거나, 구매자가 좋지 않은 물건을 비싸게 사게 된다. 노동시장이나 보험시장에서도 역선택이 문제가 되는데, 노동시장의 경우 기업이 근로자의 생산성을 잘 알 수 없어 시장균형이 사회적으로 비효율적인 상태가 될 수 있으며 보험시장의 경우에는 사고를 당할 가능성이 낮은 사람들은 보험조건이 자신들에게 불리하기 때문에 아예 보험에 가입하지 않게 되는 문제가 생긴다. 도덕적 해이는 대리인이 사용자를 위해 어떤 임무를 수행할 때 발생하는 문제로, 대리인의 부적절하거나 비도적적인 행위에 따른위험을 지칭한다. 자동차보험에 가입한 후 안전운전을 소홀히 하거나, 국민건강보험이 잘되어 있다고 해서 특별한 이상이 없는데도 병원에 자주 가는 것 등은 도덕적 해이의 예이 다. 도덕적 해이를 방지하기 위해 사용자는 대리인이 보다 성실하게 행동하도록 인센티브를 지급하거나 감시체계를 구축하는 등의 방법을 활용한다.','','ㅈㅂㄷㅈㅇㄱㄱㅈ',ARRAY['국고대리점']::text[]),
(511,'정부실패','시장실패를 교정하기 위한 정부의 시장개입과 규제가 자원배분의 효율성을 높이기보다 오히려 해치는 경우가 있는데 이를 시장실패에 비유하여 정부실패(Government Failure) 라고 한다.','시장실패를 교정하기 위한 정부의 시장개입과 규제가 자원배분의 효율성을 높이기보다 오히려 해치는 경우가 있는데 이를 시장실패에 비유하여 정부실패(Government Failure) 라고 한다. 정부실패는 규제자의 불완전한 지식·정보, 규제수단의 불완전성, 규제자의 경직성 등의 이유로 발생한다. 또한 정부는 대부분 영역에서 독점적인 지위를 갖고 있어 민간기업처럼 경쟁해야 할 필요가 없으며 성과에 따라 보상을 받는 유인제도가 부족하므로 정부실패가 발생하기도 한다. 예컨대 최근 여러 국가에서 정부는 국민의 안정된 노후생활을 보장하기 위해 사회보장제도를 시행하고 있다. 그러나 정부가 사회보장제도를 잘못 운영하면 근로능력이 있음에도 고의로 일을 하지 않는 계층이 생기고 사회보장기금이 방만 하게 운영되는 등 심각한 비효율이 초래될 수 있다. 이런 경우 정부의 시장개입이 오히려자원배분의 효율성을 악화시키는 정부실패를 가져오게 된다. 정부실패를 방지하기 위해서는 정부정책의 투명성 강화, 정부부문에의 유인제도 도입, 입법부·감사원·시민단체 등 에 의한 감시활동 강화 등의 조치가 필요하다.','','ㅈㅂㅅㅍ','{}'::text[]),
(512,'정책모기지/주택 정책대출','정부의 주택 정책목표(주거복지 증진과 대출 접근성 제고)를 달성하기 위해 정부재정을 직·간접적으로 투입하여 주택금융공사와 주택도시기금으로 하여금 구입 주택 혹은 전월세 보증금을 담보로 시중보다…','정부의 주택 정책목표(주거복지 증진과 대출 접근성 제고)를 달성하기 위해 정부재정을 직·간접적으로 투입하여 주택금융공사와 주택도시기금으로 하여금 구입 주택 혹은 전월세 보증금을 담보로 시중보다 낮은 금리로 관련 주택자금을 제공하도록 하는 다양한 주택관련 정책대출 상품(보금자리론, 디딤돌대출, 버팀목대출 등)을 의미한다. 정책모기지는 취약계층과 서민·실수요층의 주거 안정을 지원하고 주택자금 상환부담을 낮추는 한편 안심전환대출 등을 통해 주택담보대출에서 고정금리·분할상환 대출이 차지하는 비중을 높임으로써 가계부채의 질적 구조를 개선하는데 기여하고 있다. 또한 저출산·인구구조 변화에 대응하기 위해 청년·신혼부부·출산가구로 공급대상을 확대하고 지원대상 요건(연소득, 주택가격 등)도 완화하였다. 한편 보증의 형태로 주택자금을 공급하는 경우까지 포함 할 경우 주택 정책금융이란 용어를 사용하고 있다.','','ㅈㅊㅁㄱㅈ/ㅈㅌㅈㅊㄷㅊ',ARRAY['모기지대출']::text[]),
(513,'정책시차','정책시차(Policy Lag)란 어떤 경제정책을 시행해야 하는 원인이 발생하여 동 정책을 집행하는 데까지 걸리는 시간과 정책이 실제로 집행된 후 정책효과가 나타나는 데 걸리는 시간을 말한다.','정책시차(Policy Lag)란 어떤 경제정책을 시행해야 하는 원인이 발생하여 동 정책을 집행하는 데까지 걸리는 시간과 정책이 실제로 집행된 후 정책효과가 나타나는 데 걸리는 시간을 말한다. 전자를 내부시차(inside lag)라 하고 후자를 외부시차(outside lag)라고 한 다. 일반적으로 재정정책은 정책이 집행되기까지의 내부시차가 긴 반면, 정책효과가 나타나는 데 걸리는 외부시차는 짧다. 그 이유는 정부지출이나 조세제도를 변경하려면 시간이 걸리는 입법 절차를 거쳐야 하지만, 일단 정책이 집행되고 나면 총수요에 직접적인 영향을 미치기 때문이다. 한편, 통화정책의 경우는 재정정책과는 달리 내부시차는 짧지만, 생산, 물가 등 실물변수에 영향을 미치는 데는 상당한 시간이 걸리는 등 외부시차가 상대적으로 길다. 예컨대 통화정책으로 기준금리가 인하되고 그것이 금융·외환시장을 거쳐 실물부문의 가계 소비나 기업 투자 등으로 파급되기까지는 상당한 시간이 걸릴 수 있다.','','ㅈㅊㅅㅊ',ARRAY['자산유동화']::text[]),
(514,'제1차 통화조치','한국전쟁의 여파로 산업활동이 크게 위축되고 물가가 급등하는 등 경제가 큰 혼란에 빠짐에 따라 이를 타개하기 위하여 1953년 2월 15일 화폐단위를 ‘원(圓)’에서 ‘환(圜)’으로 변경하고…','한국전쟁의 여파로 산업활동이 크게 위축되고 물가가 급등하는 등 경제가 큰 혼란에 빠짐에 따라 이를 타개하기 위하여 1953년 2월 15일 화폐단위를 ‘원(圓)’에서 ‘환(圜)’으로 변경하고 100대 1로 절하(100圓 → 1圜)하는 긴급통화조치를 단행하였다. 1953년 2월 17 일부터 ‘圓’표시 한국은행권의 유통을 중지시켰으며 그 동안 한국은행권과 함께 저액면용으로 통용되어 오던 7종류 조선은행권(10圓, 5圓, 1圓, 50錢, 20錢, 10錢 및 5錢)과 일본정부의 소액보조화폐(1錢주화)의 유통도 전면 중지하고 환(圜) 표시 한국은행권만을 유일한 법화로 인정함으로써 우리나라 화폐의 완전한 독자성이 확보되었다.','','ㅈㅊㅌㅎㅈㅊ',ARRAY['제2차 통화조치']::text[]),
(515,'제2차 통화조치','정부는 1962년부터 「경제개발 5개년 계획」을 추진하면서 퇴장자금의 산업 자금화 등을 위하여 1962년 6월 10일 긴급통화조치를 단행하여 화폐단위를‘환(圜)’에서 ‘원’으로 변경하고 10대…','정부는 1962년부터 「경제개발 5개년 계획」을 추진하면서 퇴장자금의 산업 자금화 등을 위하여 1962년 6월 10일 긴급통화조치를 단행하여 화폐단위를‘환(圜)’에서 ‘원’으로 변경하고 10대 1로 절하(10圜 → 1원)하고 ‘환(圜)’ 표시 화폐의 유통과 거래를 금지하였다 (단, 50환화와 10환화는 1975년 3월 21일까지 유통). 한국은행은 긴급통화조치에 의해 500원권, 100원권, 50원권, 10원권, 5원권 및 1원권 등 6종의 새로운 은행권을 발행하고 소액거래시 1원 미만 끝자리수 처리의 편의를 도모하기 위하여 1962년 12월 1일에 10전권과 50전권도 발행하였다. 본 조치는 경제적 목적 달성보다는 ‘원’표시 도입이라는 의의를 가진다.','','ㅈㅊㅌㅎㅈㅊ',ARRAY['제1차 통화조치']::text[]),
(516,'제로금리정책','금융기관 간에 여유자금과 부족자금을 빌리는 단기금융시장에서 거래되는 초단기 자금의 금리(한국과 일본의 콜금리, 미국의 페더럴펀드금리 등)를 0%에 가까운 수준으로 떨어뜨리는 통화정책을 말한다.','금융기관 간에 여유자금과 부족자금을 빌리는 단기금융시장에서 거래되는 초단기 자금의 금리(한국과 일본의 콜금리, 미국의 페더럴펀드금리 등)를 0%에 가까운 수준으로 떨어뜨리는 통화정책을 말한다. 중앙은행이 단기금리를 제로 근처로 유도하는 것은 시중 유동성을 풍부하게 하여 금융경색을 억제하고 경기침체를 극복하기 위한 목적인 것이 보통이다.','','ㅈㄹㄱㄹㅈㅊ','{}'::text[]),
(517,'제조업생산능력/가동률지수','일본의 경우 1999년 초 일본은행이 경기활성화를 위해 콜금리를 0.02%까지 떨어뜨리며 제로금리정책을 펼쳤으나 당초 기대만큼 소비나 투자활성화가 이루어지지 않아 2006년 7월 제로금리정책을…','일본의 경우 1999년 초 일본은행이 경기활성화를 위해 콜금리를 0.02%까지 떨어뜨리며 제로금리정책을 펼쳤으나 당초 기대만큼 소비나 투자활성화가 이루어지지 않아 2006년 7월 제로금리정책을 폐기한 바 있다. 이와 관련하여 2001년 3월 일본은행은 장기간의 경기침체에서 벗어나기 위해 양적완화(QE; Quantitative Easing) 정책을 처음으로 도입했다. 양적완화는 금리가 제로(‘0’)에 가까운 상태에서 경기부양을 위해 국채 등 다양한 금융자산의 매입을 통해 시중에 돈을 공급하는 것이다. 중앙은행이 금리를 조절해 간접적으로 시중 유동성을 조절하던 전통적인 방식과 달리 양적완화는 금융자산 등을 사들이는 방법으로 시장에 통화량 자체를 늘리는 정책인데 2008년 글로벌 금융위기 이후 미국, EU, 영국 등 국제적으로 도입이 확산돼 왔다. 2008년 12월 글로벌 금융위기로 미국도 제로금리를 도입하였다.','','ㅈㅈㅇㅅㅅㄴㄹ/ㄱㄷㄹㅈㅅ',ARRAY['제조업평균가동률갭']::text[]),
(518,'제조업평균가동률갭','제조업평균가동률만으로는 경제내에 유휴생산능력이 있는지 여부와 그 크기를 판단하는 데 한계가 있게 된다.','제조업평균가동률만으로는 경제내에 유휴생산능력이 있는지 여부와 그 크기를 판단하는 데 한계가 있게 된다. 이러한 점을 고려하여 한 시점에서의 제조업평균가동률이 동 가동률의 잠재수준에서 얼마만큼의 편차를 보이는가를 계산하여 그 판단의 참고로 활용하는 데 이 편차를 제조업평균가동률갭이라 한다. 일반적으로 잠재수준은 해당연도의 장기평균(예를 들면 10년 이전 기간 제조업가동률의 평균)을 계산하여 사용한다. 제조업평균가 동률갭이 마이너스이고 절대값이 클수록 유휴생산능력이 확대되고 있는 것으로 보아 투자위축과 실업 등을 예상하게 되고, 플러스이면서 클수록 공급측면에서의 문제가 발생할가능성을 예상하게 된다.','','ㅈㅈㅇㅍㄱㄱㄷㄹㄱ',ARRAY['실업률갭']::text[]),
(519,'조세부담률','조세부담률은 국민계정에서 조세수입이 국민총소득(GNI)에서 차지하는 비중으로 정의된 다.','조세부담률은 국민계정에서 조세수입이 국민총소득(GNI)에서 차지하는 비중으로 정의된 다. 이는 국민 전체의 조세부담 정도를 나타내 주는 지표로 조세의 누진 정도, 국가의 조세징수능력 등에 따라 결정된다. 반면, 재정통계의 조세부담률은 국가 및 지방자치단체가 거둬들인 국세 및 지방세 수입이 경상금액기준 국내총생산에서 차지하는 비율로 파악된 다. 조세부담률이 높다는 것은 국민들이 벌어들인 소득 중에서 세금으로 납부하는 비중이 높다는 것이다. 조세부담률 = (국세 + 지방세)/경상GDP×100 한편, 국민부담률이란 개념도 있는데 이는 국가가 가입을 의무화하거나 재정에서 지급을 보장하는 각종 공적 사회보험에 대한 보험료 등을 조세수입에 더하여 경상GDP대비 비율을 산출한 것이다. 사회보장기여금은 4대 공적연금인 국민연금, 공무원연금, 사학연금, 군인연금과 고용보험, 산업재해보상보험, 건강보험, 노인장기요양보험 등이다. 국민부담률 = (국세+지방세+사회보장기여금)/경상GDP×100','','ㅈㅅㅂㄷㄹ',ARRAY['재정정책']::text[]),
(520,'종합금융투자사업자','신성장 동력 산업과 대규모 해외 프로젝트 등을 지원할 수 있는 투자은행 출현을 유도하기 위해 2013년 도입된 제도이다.','신성장 동력 산업과 대규모 해외 프로젝트 등을 지원할 수 있는 투자은행 출현을 유도하기 위해 2013년 도입된 제도이다. 자기자본 3조원 이상 등 일정 요건을 갖춘 증권사를 종합금융투자사업자(투자은행)로 지정하여 기업 신용공여 업무 등을 취급할 수 있도록 하고 있다. 이와 더불어 2016년 8월 제도 개편을 통해 종합금융투자사업자의 자본 확충을 통한 대형화를 유도하였는데, 자기자본이 4조원 이상인 경우 단기금융업무(만기가 1년이내인 어음의 발행, 할인, 매매, 중개, 인수 및 보증업무)를 허용하고 있으며, 8조원 이 상인 경우에는 종합투자계좌(고객으로부터 예탁 받은 자금을 통합하여 기업금융자산 등 에 운용하고 그 수익을 고객에게 지급하는 것을 목적으로 개설된 계좌(IMA; Investment Management Account) 업무를 허용하고 있다.','','ㅈㅎㄱㅇㅌㅈㅅㅇㅈ','{}'::text[]),
(521,'죄수의 딜레마','전략적 상황에 처한 경제주체들의 행동을 분석하는데 유용하게 활용되는 게임이론의 한 예로서, 협력적인 선택이 양자에게 최선임에도 불구하고 자신의 이익에 치중한 선택으로 ㅈ 인해 오히려 두 사람…','전략적 상황에 처한 경제주체들의 행동을 분석하는데 유용하게 활용되는 게임이론의 한 예로서, 협력적인 선택이 양자에게 최선임에도 불구하고 자신의 이익에 치중한 선택으로 ㅈ 인해 오히려 두 사람 모두에게 바람직하지 않은 결과를 가져오는 상황을 말한다. 죄수의 딜레마(Prisoners’ Dilemma)는 1950년 미국 프린스턴대 터커(A. Tucker) 교수가 게임 이론을 설명하기 위해 이용한 다음의 예화에서 비롯되었다. 경찰이 두 용의자 Ⅰ, Ⅱ를 격리하여 심문하면서 자백을 이끌어 내려고 다음과 같이 말하였다고 가정한다. ① 한 사람이 자백하고 다른 사람은 입을 다물었다면 자백한 사람은 1단위의 보상, 입을 다문 사람은 2단위의 벌금형이 부과된다. ② 두 사람이 모두 자백하면 각각에게는 1단위의 벌금형이 부과된다. ③ 두 사람이 모두 자백하지 않으면 Ⅰ과 Ⅱ는 혐의가 없다. 이러한 상황에서 두 사람이 직면하는 보상행렬은 아래와 같아지는데, Ⅰ과 Ⅱ는 모두 상대방의 전략과 상관없이 자백하는 전략을 선택하게 되므로 결과적으로 두 사람이 서로를 믿고 자백하지 않는 전략을 취할 때보다 나쁜 결과에 직면하게 된다. 용의자 Ⅱ 구분자백함 자백하지 않음 자백함 (-1, -1) (1, -2) 용의자 Ⅰ 자백하지 않음 (-2, 1) (0, 0) 즉 개인적인 수준에서는 합리적인 선택이 구성원 전체로 보아서는 비합리적인 선택이 되는 결과를 가져오는 딜레마를 낳게 되는데, 이 같은 죄수의 딜레마 문제는 광고경쟁, 기업의 환경오염, 국가간 군비경쟁 등 다양한 상황에 적용될 수 있다.','','ㅈㅅㅇㄷㄹㅁ',ARRAY['주당순이익(EPS)','주가순자산비율(PBR)']::text[]),
(522,'주가순자산비율(PBR)','주가순자산비율(PBR; Price to Book Ratio)은 주가를 주당순자산가치(BPS; Book- value Per Share)로 나눈 비율이다.','주가순자산비율(PBR; Price to Book Ratio)은 주가를 주당순자산가치(BPS; Book- value Per Share)로 나눈 비율이다. 즉 기업의 순자산에 비해 주가가 얼마나 높은지 또는 낮은지를 나타내는 지표이다. 대부분의 성공적인 기업의 경우 주가순자산비율이 1을 크게 상회하는데, 이는 시장이 해당 기업의 미래 성장성과 수익성을 높게 평가하고 있음을 의미한다. 기업별로 이 비율이 다른 것은 경영성과, 성장 가능성, 산업 특성 등 기업 고유의 가치 차이가 반영되기 때문이다. 증권분석가들은 종종 주가순자산비율이 낮은 주식을 주가지수가치주식, 높은 주식을 성장주식으로 분류하기도 한다.','','ㅈㄱㅅㅈㅅㅂㅇ()',ARRAY['주가수익비율(PER)']::text[]),
(523,'주가연계증권(ELS)','주가연계증권(ELS; Equity Linked Security)은 개별 주식의 가격이나 특정 주가지수의 변동에 연계되어 특정조건 충족시 약정된 투자손익이 결정되는 금융투자상품이다.','주가연계증권(ELS; Equity Linked Security)은 개별 주식의 가격이나 특정 주가지수의 변동에 연계되어 특정조건 충족시 약정된 투자손익이 결정되는 금융투자상품이다. 주가 연계증권 발행 증권사는 발행대금의 상당부분을 채권, 예금 등 안전자산에 투자하는 한편나머지를 주식, 주식관련 파생상품 등에 투자하여 약정수익 재원 확보를 위한 초과수익을 추구한다. 주가연계증권은 만기, 수익구조 등을 다양하게 설계할 수 있는 장점이 있으나 유가증권시장에 상장되지 않음에 따라 유동성이 낮고 발행증권사의 신용리스크에 노출되는 단점이 있다. 대신 기초자산이 일정수준 이상인 경우 자동 조기상환되는 조건이 부여되어 있으며 5~10%의 환매수수료를 부담하는 조건으로 발행증권사에 환매를 요구할수 있다. 한편 증권회사가 발행하는 주가연계증권과 유사한 상품으로는 자산운용사가 운용하는 주가연계펀드(ELF; Equity Linked Fund)와 은행이 취급하는 주가연계예금(ELD; ㅈ Equity Linked Deposit) 등이 있다. 주가연계증권은 1980년대 후반 미국, 홍콩 등에서 판매되기 시작하였으며, 우리나라에서는 2003년 2월 판매가 허용되었다. 발행방식은 공모보다 사모가 많은 편이며 투자자는 개인 및 일반법인이 절반 이상을 차지하는 가운데자산운용사, 퇴직연금, 신탁 등도 투자하고 있다.','','ㅈㄱㅇㄱㅈㄱ()','{}'::text[]),
(524,'주가지수','주가지수는 주식가격의 전반적인 수준을 나타내는 지표이다.','주가지수는 주식가격의 전반적인 수준을 나타내는 지표이다. 주식시장에서는 매일 수많은 종목이 거래되는데, 이러한 각 개별종목의 가격변동을 종합하여 주식가격의 전반적인 움직임을 파악하기 위하여 작성되는 지수가 주가지수이다. 주가지수는 기준시점의 시장전체 주가수준과 비교시점의 시장전체 주가수준을 비교하여 산출되는데, 그 방식에 는 주가평균식과 시가총액 가중식이 있다. 주가평균식은 대상 종목의 주가를 단순 합산하여 종목수로 나누는 방식인데, 미국의 다우존스 산업평균과 일본의 닛케이 평균주가 가 대표적이다. 시가총액 가중식은 개별주식의 주가에 상장주식수를 가중한 주가지수로, 일정 시점의 시가총액과 현재 시점의 시가총액을 비교하여 현재의 주가수준을 판단하는 방식이다. 우리나라의 코스피 및 코스닥, 미국의 S&P500과 NASDAQ, 일본의 TOPIX 등 세계 주요국의 주가지수는 대부분 시가총액 가중식에 의해 산출되고 있다. 이와 같은 주가지수는 주식 투자 판단의 주요 척도로서 투자자의 합리적인 의사결정 자료로는 물론 정책당국의 정책결정 참고자료로도 활용된다.','','ㅈㄱㅈㅅ',ARRAY['주가수익비율(PER)']::text[]),
(525,'주가지수선물거래','주가지수선물의 거래유형으로는 헤지거래, 투기거래, 차익거래, 스프레드거래 등이 있다.','주가지수선물의 거래유형으로는 헤지거래, 투기거래, 차익거래, 스프레드거래 등이 있다. 헤지거래는 현물(주식)포지션과 반대방향으로 선물을 매수 또는 매도함으로써 현물시장에서 주가변동의 위험을 회피하는 것을 말한다. 따라서 헤지거래자는 주가변동 위험을 회피할 수 있지만, 주가 상승시 이익을 얻을 수 있는 기회도 상실하게 된다. 투기거래는 현물포지션 보유여부에 관계없이 선물 자체의 매매차익을 겨냥한 거래이다. 약정금액의 일부만으로 선물을 매매할 수 있다는 점으로 인해 레버리지 효과(leverage effect)가 발생하므로 현물투자보다 위험이 크다. 차익거래는 선물가격과 현물가격간 차이가 적정수준을 초과할 경우 선물과 현물중 상대적으로 고평가된 것을 매도하고 저평가된 것을 매수한 후 양자간 가격차가 해소 또는 역전되었을 때 청산거래(반대매매)를 함으로써 무위험차익을 얻는 거래기법이다. 스프레드거래는 만기나 기초자산이 상이한 주가지수선물간의 가격차이를 이용하여 수익을 획득할 목적으로 양 종목의 매입·매도포지션을 동시에 보유하는 거래를 말한다. 이는 기초자산이 동일한 주가지수선물의 결제월물별 가격차이를 이 용하는 만기간 스프레드(calendar spread) 거래와 기초자산이 상이한 주가지수선물을 대상으로 하는 시장간 스프레드(inter-market spread) 거래로 구분된다.','','ㅈㄱㅈㅅㅅㅁㄱㄹ',ARRAY['레버리지 효과']::text[]),
(526,'주가지수옵션','주가지수옵션(Stock Index Options)은 주가지수(기초자산)를 만기일에 사전에 약정한 가격(행사가격)으로 매입하거나 매도할 수 있는 권리를 거래하는 파생금융상품으로서','주가지수옵션(Stock Index Options)은 주가지수(기초자산)를 만기일에 사전에 약정한 가격(행사가격)으로 매입하거나 매도할 수 있는 권리를 거래하는 파생금융상품으로서','','ㅈㄱㅈㅅㅇㅅ','{}'::text[]),
(527,'주당순이익(EPS)','매입권리인 콜옵션(call option)과 매도권리인 풋옵션(put option)으로 구분된다.','매입권리인 콜옵션(call option)과 매도권리인 풋옵션(put option)으로 구분된다. 옵션의 매도자는 매수자에게 옵션을 제공하고 매수자는 그 대가로 프리미엄(옵션가격)을 지급한다. 콜옵션 매수자는 만기일에 기초자산가격(코스피200 종가 등)이 행사가격을 넘어서 면 권리를 행사할 유인이 발생하며, 기초자산가격이 행사가격에 프리미엄을 더한 값을 초과하는 금액만큼 매수자의 이익(매도자의 손실)이 된다. 풋옵션 매수자는 만기일에 기초자산가격(코스피200 종가 등)이 행사가격보다 낮아야만 권리를 행사할 유인이 발생하며, 기초자산가격이 행사가격에서 프리미엄을 차감한 값을 하회하는 금액만큼 풋옵션 매수자의 이익(매도자의 손실)이 된다. 주가지수옵션은 주가지수선물과 마찬가지로 실물이 존재하지 않는 주가지수를 대상으로 하고 있으나 거래의 목적물이 권리라는 점에서 주가지수선물과 다르다. 또한 주가지수옵션은 주가지수선물과 달리 기초자산 가격변동에 따른 손익구조가 비대칭적이다. 옵션매수자는 손실이 프리미엄으로 한정되는 반면 이익은 기초자산가격에 비례하여 증가하고, 역으로 옵션매도자는 이익이 프리미엄에 국한되는 반면손실은 제한이 없다. 주가지수옵션시장은 1983년 3월 미국의 시카고옵션거래소(CBOE; Chicago Board Options Exchange)에서 S&P100지수를 대상으로 최초로 개설되었으며 우리나라에서는 1997년 7월에 코스피200 옵션시장이, 2001년 11월에 코스닥50 옵션시장이 개설되었다. ㅈ','','ㅈㄷㅅㅇㅇ()',ARRAY['주가지수선물거래']::text[]),
(528,'주식시장','주식시장은 주식회사의 지분권을 표시하는 유가증권인 주식이 거래되는 시장이다.','주식시장은 주식회사의 지분권을 표시하는 유가증권인 주식이 거래되는 시장이다. 주식시장은 기업공개, 유상증자 등을 통해 주식이 새롭게 공급되는 발행시장과, 이미 발행된 주식이 투자자간에 거래되는 유통시장으로 나누어진다. 발행시장은 새로운 주식이 최초로 출시되는 시장으로 제1차 시장(primary market)이라고도 한다. 발행시장은 기업, 금융기관 등 자금수요자인 발행인, 자금공급자인 투자자, 주식발행사무를 대행하고 발행위험을 부담하는 인수인으로 구성된다. 유통시장은 이미 발행된 주식이 매매되는 시장으로 제2차 시장(secondary market)이라고도 한다. 유통시장은 발행된 주식의 시장성과 환금성을 높여주고 자유경쟁을 통해 공정한 가격을 형성하는 역할을 한다. 우리나라의 주식 유통시장에는 유가증권시장, 코스닥시장, 코넥스시장, K-OTC시장이 있다. 이 중 유가증권시장, 코스닥시장 및 코넥스시장은 한국거래소에서 개설·운영하는 장내시장이며, K-OTC시장은 장외시장이다. 유가증권시장은 동 시장의 시가총액이 우리나라 대표 주가 지수인 코스피의 산출 기준이 되므로 코스피시장이라고도 한다. 한편, 주식이 장내시장에 서 매매되기 위해서는 상장이라는 등록절차를 거쳐야 한다. 유통시장에서 투자자의 매매주문은 투자중개업을 영위하는 금융투자회사를 거쳐 한국거래소에서 체결되며, 이에 따른 결제는 매매일로부터 3일째 되는 날 한국예탁결제원을 통해 이루어진다.','','ㅈㅅㅅㅈ',ARRAY['유통시장','발행시장']::text[]),
(529,'주주환원정책','주주환원정책은 배당 확대, 자사주 매입 등 주주가치를 제고할 수 있는 정책을 의미한다.','주주환원정책은 배당 확대, 자사주 매입 등 주주가치를 제고할 수 있는 정책을 의미한다. 배당을 늘리면 주주에게 지급되는 현금이 증가하여 직접적인 수익 환원이 이루어지고, 자사주를 매입하면 시장에 유통되는 주식수가 감소하여 주가 상승 효과를 기대할 수 있다. 이러한 정책장기투자를 유도하고, 기업에 대한 시장의 신뢰를 높이는 데 목적이 있다.','','ㅈㅈㅎㅇㅈㅊ','{}'::text[]),
(530,'주택저당증권(MBS)','주택저당증권(MBS) 주택저당증권(MBS; Mortgage-Backed Securities)이란 자산유동화증권(ABS)의 일종으로써 모기지(또는 주택담보대출)를 기초자산으로 발행되는 증권이다.','주택저당증권(MBS) 주택저당증권(MBS; Mortgage-Backed Securities)이란 자산유동화증권(ABS)의 일종으로써 모기지(또는 주택담보대출)를 기초자산으로 발행되는 증권이다. 원래 주택저당증권은 미국에서 제2차 세계대전 이후 참전한 군인들의 주거 안정을 위해 도입된 제도 인데 우리나라에서는 IMF 외환위기 이후 본격적으로 취급되기 시작하였다. MBS시장은 세 종류의 시장으로 구분되는데 1차 시장은 모기지 차입자와 모기지 대출기관 사이에 모기지론이 이루어지는 시장이며, 2차 시장은 모기지 대출기관이 보유하고 있는 모기지를 유동화(증권화)하는 시장이며 자본시장은 모기지가 유동화된 주택저당증권이 투자자에 게 매각되고 유통되는 시장을 말한다. 주택저당증권은 일반 채권과는 다른 특징을 보유하고 있다. 보통 채권은 발행자가 원리금 상환을 부담하는데 반해 MBS는 통상 기초자산을 특수목적회사(SPC)에 이전하고 SPC가 발행하는 것이기 때문에 원리금 상환이 발행자의 신용에 기초하기보다는 기초자산의 현금 흐름에 의존하게 된다. 또한 MBS에는 조기상환위험(prepayment risk)이라는 독특한 위험이 존재한다. 시장금리가 하락하는 경우에는 기존 모기지 차입자가 이자비용 절감을 위해 동 모기지를 조기에 상환하고 금리가 더 낮은 모기지론을 받게 되는데 모기지 상환이 이루어지면 그것을 기초자산으로 하 ㅈ 고 있는 MBS도 조기에 상환이 이루어지게 된다. 이것을 투자자 입장에서 보면 자산 듀레이션이 당초 예상보다 줄어들어 국채 추가 매입 등 자산 듀레이션을 더 늘려야 하는 문제(반대로 시장금리가 상승하는 경우에는 자산 듀레이션이 당초 예상보다 늘어나 보유채권 매각 등 자산 듀레이션을 줄여야 하는 문제)를 야기한다. 그래서 투자자는 MBS를 투자할 때는 적정 조기상환율을 산정하고 이를 토대로 투자를 하게 된다. 은행이 보유하고 있는 모기지를 유동화하는 경우 모기지론에서 발생하는 이자수익은 줄어들지만 매각대금으로 모기지를 추가로 취급할 수 있는 여력이 생기며 위험자산이 줄어들기 때문에 BIS비율이 올라가는 긍정적인 효과를 기대할 수 있다. 현재 우리나라에서는 은행이 모기지론을 취급하며 한국주택금융공사가 동 모기지를 유동화하여 자본시장에 매각하는 형태로 이루어지고 있다.','','ㅈㅌㅈㄷㅈㄱ()',ARRAY['자산유동화','모기지대출']::text[]),
(531,'중간소비','생산과정에서 원재료, 광열비, 간접비 등으로 소비된 비내구재 및 서비스를 말하는 것으로써 고정자산의 유지보수를 위한 지출 등이 포함되고 중고품과 폐품의 순판매액은 차감된다.','생산과정에서 원재료, 광열비, 간접비 등으로 소비된 비내구재 및 서비스를 말하는 것으로써 고정자산의 유지보수를 위한 지출 등이 포함되고 중고품과 폐품의 순판매액은 차감된다. 중간소비(Intermediate Consumption)는 최종소비지출과 혼돈을 가져올 수 있는 데 양자는 재화와 용역이 생산에 투입되는가 혹은 소비주체에 의해 소비되는가에 의해 구분된다. 예를 들어 똑같은 비누와 수건이라 하더라도 기업주가 공장이나 사무실에서 근로 자들이 사용할 목적으로 구매하였다면 중간소비로 계상되나 근로자가 가정에서 사용할목적으로 구매하였다면 최종소비지출로 처리된다. 한편, 중간소비와 자본형성은 생산자가 구매한 재화가 회계기간 중에 소진 되는가 혹은 회계기간 이후에도 이익의 원천이 되는가에 따라 구분된다.','','ㅈㄱㅅㅂ',ARRAY['최종수요/중간수요']::text[]),
(532,'중개무역','수출입 양 당사자 간의 물품거래가 제3국 상인의 중개로 이루어지는 무역형태를 말한다.','수출입 양 당사자 간의 물품거래가 제3국 상인의 중개로 이루어지는 무역형태를 말한다. 거래물품은 제3국 상인을 거쳐서(제3국에 일단 양륙) 인도되는 예도 있으나 수출자로부터 수입자에게 직접 보내어지는 것이 일반적이다. 대금의 결제는 수출자가 수입자로부터직접 회수하여 제3국의 상인에게 수수료만을 지급하는 경우도 있으나, 수출자는 제3국의 상인으로부터, 제3국의 상인은 수입자로부터 무역대금을 회수하는 것이 일반적이다. 중계무역과의 중요한 차이는 제3국 상인이 수출입거래의 당사자가 되어 매매차익을 취하는 것이 아니라 단지 중개수수료만을 목적으로 거래한다는 것이다.','','ㅈㄱㅁㅇ',ARRAY['중계무역']::text[]),
(533,'중계무역','물품을 수입하되 이를 국내에 반입하지 아니하고 가공하지 않은 원형 그대로 직접 제3 국으로 수출하는 형태의 무역거래를 말한다.','물품을 수입하되 이를 국내에 반입하지 아니하고 가공하지 않은 원형 그대로 직접 제3 국으로 수출하는 형태의 무역거래를 말한다. 중계무역업자는 수출입의 당사자로서 자기 책임 하에 수입 및 수출을 하고 대금결제를 한다는 점에서 수출입의 주체가 되지 않고 중앙예탁기관단순히 중개수수료만을 취득하는 중개무역과 구분된다.','','ㅈㄱㅁㅇ',ARRAY['중개무역']::text[]),
(534,'중앙거래당사자','중앙거래당사자(CCP; Central Counterparty)는 증권거래 계약의 매도자에 대해 매수자역할을, 매수자에 대해서는 매도자 역할을 수행하는 기관으로서 다자간 차감에 의한 청산업무를…','중앙거래당사자(CCP; Central Counterparty)는 증권거래 계약의 매도자에 대해 매수자역할을, 매수자에 대해서는 매도자 역할을 수행하는 기관으로서 다자간 차감에 의한 청산업무를 수행하여 결제 유동성을 절약하는 한편 결제이행보증 서비스를 제공하여 참가자의 리스크관리 부담을 경감시키고 신용 및 유동성리스크를 집중하여 관리하는 역할을 수행하고 있다. 한편 글로벌 금융위기 이후 모든 표준화된 장외파생상품거래의 중앙거래당사자를 통한 청산이 의무화됨에 따라 결제리스크가 집중되는 중앙거래당사자에 대한 리스크 관리의 중요성이 더욱 커지고 있다. 우리나라의 장내 증권 및 파생상품 거래는 한국거래소가 중앙거래당사자 역할을 수행하고 있다. 장외거래의 경우 금융위원회로부터 금융투자상품거래청산업 인가를 받은 한국거래소와 한국예탁결제원이 각각 장외파생상품거래(원화 이자율스왑거래)와 주식기관투자자거래(상장주식의 위탁매매거래)에 대해 중 ㅈ 앙거래당사자의 역할을 하고 있다.','','ㅈㅇㄱㄹㄷㅅㅈ',ARRAY['지급결제시스템']::text[]),
(535,'중앙예탁기관','중앙예탁기관(CSD; Central Securities Depository)은 각종 증권을 집중적으로 예탁받아 관리하는 기관으로서, 증권 발행 및 유통시장에서 예탁자와 예탁자의 고객을 대상으로…','중앙예탁기관(CSD; Central Securities Depository)은 각종 증권을 집중적으로 예탁받아 관리하는 기관으로서, 증권 발행 및 유통시장에서 예탁자와 예탁자의 고객을 대상으로 증권의 예탁, 계좌대체, 예탁증권의 권리행사 등의 업무를 수행한다. 또한 중앙예탁기관은 금융시장에서 거래되는 증권을 집중 보관함으로써 증권결제가 실물증권의 이동 없이 계좌대체방식으로 이루어질 수 있도록 한다. 금융시장의 증권결제는 대부분 계좌대체방식으로 이루어지고 있으므로 중앙예탁기관은 통상 증권매매거래의 결제 과정에서 증권이전(delivery)을 책임지는 기관으로서의 역할을 수행하고 있다. 현재 각국에서는 단일이 나 소수의 중앙예탁기관이 증권의 예탁 및 이전 업무를 수행하고 있으며 우리나라에서는 한국예탁결제원이 동 업무를 수행하고 있다.','','ㅈㅇㅇㅌㄱㄱ',ARRAY['계좌대체']::text[]),
(536,'중앙은행','일반적으로 중앙은행은 독점적 발권력을 바탕으로 금융기관에 부족자금을 대출하는 은행의 은행 기능과 정부의 세입 및 세출을 관리하고 필요시 부족자금을 대출하는 정부의 은 행 기능을 수행한다.','일반적으로 중앙은행은 독점적 발권력을 바탕으로 금융기관에 부족자금을 대출하는 은행의 은행 기능과 정부의 세입 및 세출을 관리하고 필요시 부족자금을 대출하는 정부의 은 행 기능을 수행한다. 아울러 통화량 및 금리 조절을 통해 물가안정을 포함한 거시경제의 안정을 도모하는 한편 최종대부자 역할, 거시건전성 정책 등을 통해 금융안정에도 기여한 다. 중앙은행이 처음부터 이러한 기능을 모두 수행한 것은 아니며 경제발전에 따라 진화하면서 여러 기능이 추가되었다. 중앙은행의 효시로는 1694년에 설립된 영란은행(Bank of England)을 꼽을 수 있다. 당시 영란은행은 상업은행이었으나 정부의 은행 역할을 수행하면서 화폐발행에 대한 독점권을 부여받았고 점차 은행의 은행 기능을 확대하면서 오늘날과 같은 모습을 갖추게 되었다. 20세기 이후에는 금본위제가 폐지되고 화폐의 적정관리가 중요해지면서 통화량, 금리, 환율 등의 관리를 통해 물가안정을 포함한 거시경제의 안정을 도모하는 통화신용정책이 중앙은행의 핵심기능으로 자리 잡게 되었다. 1970~80년대에 는 석유파동 외채위기 등에 따른 물가불안과 경기침체에 대응하여 거시경제 안정화 노력을 강화하였고 이 과정에서 통화신용정책의 중립성을 제고하기 위한 제도개선이 있었다. 1990년대 이후에는 금융자유화 등에 따른 새로운 금융상품의 출현 등으로 통화량 관리가 한계를 보이면서 한국은행을 비롯한 다수의 중앙은행이 물가안정목표제를 도입하였다. 한 편 2008년 글로벌 금융위기를 계기로 거시건전성 정책의 중요성이 커지면서 미국 등 각국중앙은행의 금융안정 기능을 강화하는 방향으로 제도개편이 이루어졌다.','','ㅈㅇㅇㅎ',ARRAY['금융안정','금본위제']::text[]),
(537,'중앙은행 디지털화폐(CBDC)','중앙은행 디지털화폐(CBDC; Central Bank Digital Currency)는 중앙은행 내 지준예치금이나 결제성 예금과는 별도로 중앙은행이 발행하는 새로운 전자적 형태의 화폐를 의 미한다.','중앙은행 디지털화폐(CBDC; Central Bank Digital Currency)는 중앙은행 내 지준예치금이나 결제성 예금과는 별도로 중앙은행이 발행하는 새로운 전자적 형태의 화폐를 의 미한다. 2010년대 중반 비트코인과 분산원장기술이 주목을 받기 시작한 이후 중앙은행증권결제리스크디지털화폐에 대한 관심이 크게 증대되었으며 2015년 영란은행이 CBDC란 용어를 최초로 사용하였다. 한편 이용주체에 따라 모든 경제주체가 이용할 수 있는 소액결제용 CBDC 와 금융기관이 이용하는 거액결제용 CBDC로 구분하며 구현방식에 따라 현재와 같은 계좌방식의 단일원장방식과 분산원장방식으로 구분된다. 다만 단일원장기반 거액결제용 CBDC는 기존의 지준예치금 이나 결제성예금과 개념상 동일하므로 국제기구 등에서는 분산원장기반 거액결제용 CBDC만을 거액결제용 CBDC로 분류한다. 최근 들어 글로벌 빅테크 기업 등이 발행한 스테이블코인의 확산 가능성 및 부작용에 대한 우려가 커짐에 따라중앙은행에 대한 신뢰를 기반으로 발행되는 CBDC에 대한 관심이 더욱 높아지고 있다.','','ㅈㅇㅇㅎㄷㅈㅌㅎㅍ()',ARRAY['스테이블코인','분산원장 기술','지준예치금']::text[]),
(538,'증거금','증권 현물을 거래할 경우 또는 선물/옵션을 거래할 경우에 매매당사자 일방 또는 매매당사자 쌍방이 매매약정을 이행한다는 증거로 중개회사에 예치하는 금액을 말한다.','증권 현물을 거래할 경우 또는 선물/옵션을 거래할 경우에 매매당사자 일방 또는 매매당사자 쌍방이 매매약정을 이행한다는 증거로 중개회사에 예치하는 금액을 말한다. 주식 현물매수 주문시 사고자 하는 주식 매입금액의 일정비율에 해당하는 금액을 증거금으로 미 ㅈ 리 예치해야 하며 나머지 대금은 매수가 이루어진 후 실제 결제일에 납부한다. 선물거래에서도 가격변동에 따른 계약불이행을 방지하기 위해 담보적 성격의 증거금을 납부한다. 선물거래에서 증거금을 납부함으로써 가격 하락시에는 매수자의 계약불이행 가능성으로 부터 매도자를 보호하고 가격 상승시에는 매도자의 계약불이행 가능성으로부터 매수자를 보호할 수 있다. 증거금에는 고객이 중개회사에 납부하는 위탁증거금과 중개회사가 고객으로부터 받은 증거금 중 일부를 결제기관에 납부하는 매매증거금이 있다.','','ㅈㄱㄱ',ARRAY['증권결제리스크']::text[]),
(539,'증권결제리스크','증권결제리스크는 매매증권의 인도와 대금지급이 예정대로 이행되지 않아 발생할 수 있는 손실가능성을 말하며 원금리스크, 대체비용리스크, 유동성리스크 등으로 구분된다.','증권결제리스크는 매매증권의 인도와 대금지급이 예정대로 이행되지 않아 발생할 수 있는 손실가능성을 말하며 원금리스크, 대체비용리스크, 유동성리스크 등으로 구분된다. 원금리스크는 증권매도자가 증권을 인도했지만 매수자가 대금을 지급하지 않거나 증권매수자가 대금을 지급했지만 증권을 인도받지 못할 가능성을 말한다. 대체비용리스크는 매매계약 체결 후 거래 당사자 일방이 계약을 취소하여 원래의 거래를 다른 계약으로 대체할 때 발생한다. 유동성리스크는 증권거래가 발생한 후 거래당사자 일방이 일시적인 유동성 부족으로 예정된 시간에 결제를 하지 못할 가능성을 말한다. 증권결제는 자금결제와 달리 대금과 증권의 상호이전을 통해 결제되며 리스크 발생 대부분은 주로 결제일에 증권인도와 대금지급과정에서 현실화한다. 증권인도와 대금지급이 개별적으로 이루어지는 분리결제(free of payment) 방식은 매매당사자 일방에게 원금리스크가 발생하므로 증권대금동시결제(DVP) 방식을 채택함으로써 증권결제리스크를 크게 감축할 수 있다.','','ㅈㄱㄱㅈㄹㅅㅋ',ARRAY['증권대금동시결제(DVP)','분리결제']::text[]),
(540,'증권대금동시결제(DVP)','증권대금동시결제(DVP; Delivery versus Payment)는 중앙예탁기관의 증권결제시스템을 대금결제은행의 지급시스템과 연계하여 증권 인도를 전제로 자금을 지급하거나 자금지급을 전제로…','증권대금동시결제(DVP; Delivery versus Payment)는 중앙예탁기관의 증권결제시스템을 대금결제은행의 지급시스템과 연계하여 증권 인도를 전제로 자금을 지급하거나 자금지급을 전제로 증권을 인도하는 방식이다. 이 방식은 증권인도시기와 대금지급시기가 서 로 달라 거래당사자중 한쪽이 계약을 불이행할 경우 발생하는 원금리스크를 근본적으로 제거할 수 있기 때문에 증권결제리스크를 관리하는 데 효과적이다. 「지급결제 및 시장인프라위원회」(CPMI)와 「국제증권감독기구」(IOSCO)에서 제정한 국제기준인 「금융시장인프라에 관한 원칙」(PFMI)에서도 증권결제시스템은 DVP방식을 이용함으로써 원금리스크를 제거하도록 권고하는 등 국제적으로 증권결제시스템이 준수해야 할 결제표준이 되고 있다. 우리나라의 경우 장내 주식거래와 장내국채 및 RP거래, 장외채권거래 등 주요 증권거래에 대하여 한은금융망과 한국예탁결제원의 증권결제시스템을 연계하여 DVP 방식으로 결제하고 있다.','','ㅈㄱㄷㄱㄷㅅㄱㅈ()',ARRAY['분리결제','외환동시결제(PVP)']::text[]),
(541,'증권커스터디서비스','증권커스터디서비스는 유가증권에 투자하는 투자자를 대신하여 해당 증권의 보고 (safekeeping) 및 기록(record keeping), 이전(delivery), 원리금 및 배당금 수령, 통지등…','증권커스터디서비스는 유가증권에 투자하는 투자자를 대신하여 해당 증권의 보고 (safekeeping) 및 기록(record keeping), 이전(delivery), 원리금 및 배당금 수령, 통지등 제반 관리서비스를 제공하는 업무를 말한다. 예를 들어, 외국인 투자자가 국내 증권에 지급결제 및 시장인프라 위원회(BIS CPMI) 투자할 때 시중은행 및 외국계은행 등의 커스터디기관이 실물증권 반출의 어려움이나 법적·행정적 복잡성을 해소해 주는 증권커스터디서비스를 제공하고 있다. 또한 외국 중앙은 행이 국내 채권에 투자할 경우, 커스터디기관인 한국은행을 통해 보호예수, 원리금 수령, 매매대금 결제, 환전, 여유자금 운용 등의 서비스를 이용할 수 있다. 이처럼 증권커스터디서비스는 투자자 자산을 외부 도난, 해킹, 분실 등 위험으로부터 보호하고, 법적·기술적안전성을 제공한다.','','ㅈㄱㅋㅅㅌㄷㅅㅂㅅ','{}'::text[]),
(542,'증시주변자금','증시주변자금은 주식시장에 직접 투자되지는 않지만, 언제든지 유입될 수 있는 대기성 자금이다.','증시주변자금은 주식시장에 직접 투자되지는 않지만, 언제든지 유입될 수 있는 대기성 자금이다. MMF, CMA, 예탁금, 펀드 대기자금, 투자자 예수금 등이다. 증시 호조 기대시 이 자금이 주식시장으로 유입되어 지수 상승에 기여할 수 있다. 시장의 유동성과 투자 여력, 투자 심리 등을 파악하는데 중요한 지표로 활용된다. 지급 ㅈ 지급(Payment)은 개인이나 기업 등 경제주체가 경제거래를 한 후 현금, 수표, 신용카드, 자금이체 등 지급수단을 이용하여 예금 등 화폐적 가치에 대한 청구권을 이전하는 행위를 말한다. 지급이 현금으로 이루어지는 경우에는 별도의 자금 이전이 필요 없어 청산기관과 결제기관의 청산 및 결제과정이 필요 없으나 수표나 자금이체 등 비현금수단으로 지급하는 경우에는 지급인과 수취인의 거래은행 사이에 별도의 청산 및 자금이체를 통해 자금이 이전되어야 결제가 완료된다.','','ㅈㅅㅈㅂㅈㄱ',ARRAY['청산','결제']::text[]),
(543,'지급결제 및 시장인프라 위원회 (BIS CPMI)','국제결제은행(BIS)의 「지급 및 시장인프라 위원회」 (CPMI; Committee on Payments and Market Infrastructures)는 1990년 설립된 「지급결제제도위원회」…','국제결제은행(BIS)의 「지급 및 시장인프라 위원회」 (CPMI; Committee on Payments and Market Infrastructures)는 1990년 설립된 「지급결제제도위원회」(CPSS; Committee on Payment and Settlement Systems)의 명칭을 2014년 9월 1일부터변경한 것으로, 처음에는 주요국의 지급결제제도 동향을 모니터링하고 분석하기 위해 설립되었다. 현재는 「금융시장인프라에 관한 원칙」 등 국제기준 제정 및 이행상황 모니터링, 금융시장인프라 감시와 관련한 정책 개발 및 제안 주도, 중앙은행 간 협력 증진 및 정보교환 촉진 등의 기능을 수행하고 있다. 2022년 9월말 현재 CPMI에는 28개국 중앙은행이 참여 중이며 한국은행은 2009년 7월 24일 회원으로 가입하였다.','','ㅈㄱㄱㅈㅁㅅㅈㅇㅍㄹㅇㅇㅎ()',ARRAY['국제결제은행(BIS)','지급결제시스템']::text[]),
(544,'지급결제보고서','한국은행이 매년 발행하는 지급결제보고서는 국내 지급결제제도의 운영 현황, 지급결제시스템별 동향, 정책 추진 및 혁신 노력, 주요 현안 분석 등을 종합적으로 담은 공식 보고 서이다.','한국은행이 매년 발행하는 지급결제보고서는 국내 지급결제제도의 운영 현황, 지급결제시스템별 동향, 정책 추진 및 혁신 노력, 주요 현안 분석 등을 종합적으로 담은 공식 보고 서이다. 이 보고서는 거액결제시스템, 소액결제시스템, 외환동시결제시스템, 증권결제시스템 등 각 지급결제시스템의 연간 결제 동향과 결제리스크 관리 현황을 상세히 분석하며 지급결제제도의 안전성과 효율성 제고를 위한 제도 개선, 인프라 확충, 지급수단의 편의 성 강화, 국제협력 활동 등 한국은행의 주요 정책 추진 내용을 포함한다. 특히, 지급결제시스템의 안정적 운영을 위해 한은금융망 등 핵심 인프라의 관리, 담보제도 개선, 금융기관 대상 점검 및 감시 활동, 결제리스크 관리제도 운용 현황을 분석한다. 최근에는 디지털자산시장 확대 등 지급결제 환경변화에 대응한 정책 방향과 중앙은행 디지털화폐(CBDC) 관련 현황, 가상자산 등 신종 지급수단의 현황 분석 등도 주요 내용으로 다루고 있다.','','ㅈㄱㄱㅈㅂㄱㅅ',ARRAY['지급결제시스템']::text[]),
(545,'지급결제시스템','개인·기업·정부 등 경제주체들의 금융거래나 경제활동에서 발생하는 지급, 청산 및 결제가 원활히 이루어지도록 해주는 금융시스템의 하부구조로서 중앙은행, 은행, 청산기관, 관련 법규, 지급수단 등으로…','개인·기업·정부 등 경제주체들의 금융거래나 경제활동에서 발생하는 지급, 청산 및 결제가 원활히 이루어지도록 해주는 금융시스템의 하부구조로서 중앙은행, 은행, 청산기관, 관련 법규, 지급수단 등으로 구성된다. 지급결제시스템은 시장경제 하에서 각종 경제활동이 실행되는 금융 하부구조로서 기능하기 때문에 효율적이고 안정적인 지급결제시스템은 금융제도의 발전과 건전한 신용질서를 유지하기 위한 근간이 된다.','','ㅈㄱㄱㅈㅅㅅㅌ',ARRAY['거액지급시스템','소액지급시스템','지급수단']::text[]),
(546,'지급결제제도 감시','국제결제은행(BIS)의 지급결제 및 시장인프라 위원회는 지급결제제도 감시(Oversight of Payment Systems)를 “기존 시스템 및 구축 예정인 시스템을 모니터링하고 동 시스템에…','국제결제은행(BIS)의 지급결제 및 시장인프라 위원회는 지급결제제도 감시(Oversight of Payment Systems)를 “기존 시스템 및 구축 예정인 시스템을 모니터링하고 동 시스템에 대해 평가하는 한편, 필요시 개선을 유도함으로써 동 시스템들의 안전성 및 효율성의 증진을 도모하는 중앙은행의 기능”으로 정의하고 있다. 즉, 지급결제제도 감시의 개념에는 공공정책 목표(안전성 및 효율성), 감시범위(지급결제시스템), 감시활동(모니터링, 평가 및 개선 권고)의 세 가지 요소와 지급결제제도에 대한 중앙은행의 책무라는 의미가 함께들어 있다. 지급결제제도에 대한 중앙은행의 감시가 필요한 이유는 시장경제가 원활하게작동하는 데 있어 지급결제시스템의 역할이 매우 중요하기 때문이다. 경제적 거래에 수반되는 자금, 증권 및 외환의 이동은 대부분 지급결제시스템을 통해 이루어지기 때문에 원활한 지급결제는 시장이 제 기능을 하는 데 필수적이다. 또한 대부분의 지급결제시스템은 민간부문에 의해 구축·운영되는 것이 일반적인데 일부 시스템의 경우 시장실패로 인해 사회적으로 최적수준의 안전성과 효율성을 달성하지 못할 가능성이 있어 공공부문의 개입이 필요하게 된다.','','ㅈㄱㄱㅈㅈㄷㄱㅅ',ARRAY['지급결제 및 시장인프라 위원회(BIS CPMI)','결제리스크']::text[]),
(547,'지급수단','지급수단(Payment Instruments)은 크게 현금과 현금 이외의 지급수단으로 구분된다.','지급수단(Payment Instruments)은 크게 현금과 현금 이외의 지급수단으로 구분된다. 현금 이외의 지급수단은 금융기관에 자금의 이전을 요청하는 수단을 말하는데 여기에는 계좌이체, 지급카드, 어음이나 수표 등이 포함된다. 또한 지급수단은 지급결제과정에서 종이로 제작된 지급수단인 장표가 실제로 이동하는지 여부에 따라 장표방식 지급수단과 전자방식 지급수단으로 구분할 수도 있다. 장표방식 지급수단에는 어음, 수표, 지로 등이 있으며 전자방식 지급수단에는 신용카드, 체크카드 등이 있다. 최근에는 지급서비스 제공방식이 다양화되면서 전통적인 지급수단 분류방식 대신 인터넷뱅킹, 모바일 지급카드 등 접근채널별로 분류하기도 한다.','','ㅈㄱㅅㄷ',ARRAY['지급결제시스템']::text[]),
(548,'지급여력비율/K-ICS비율','보험회사의 지급여력(Solvency Margin)을 나타내는 지표로, 「보험업법 시행령」에서는 지급여력금액을 지급여력기준금액으로 나눈 비율로 규정하고 있다.','보험회사의 지급여력(Solvency Margin)을 나타내는 지표로, 「보험업법 시행령」에서는 지급여력금액을 지급여력기준금액으로 나눈 비율로 규정하고 있다. 이 비율이 높을수록보험회사가 예상 밖의 손실 발생이나 자산가치 하락에 직면하더라도 보험금을 문제없이 지급할 수 있는 지급능력(solvency)이 높다(혹은 예기치 않은 리스크가 발생하더라도 이 에 대한 손실흡수능력이 양호하다)는 것을 의미한다. 2023년부터 보험회사에 새로운 회계기준(금융자산 분류 및 측정(IFRS9), 보험계약(IFRS17))이 도입되면서 지급여력금액 (가용자본)과 지급여력기준금액(요구자본)의 산정 방식도 기존 위험기준 자기자본(Risk- Based Capital) 제도에서 K-ICS제도로 전면 개편되었다. K-ICS제도 하에서 지급여력금액(가용자본)은 시가평가된 자산에서 부채를 차감한 순자산을 산출하고 여기에 손실흡수성 정도에 따라 일부 항목을 가감하여 측정한다. 지급여력기준금액(요구자본)은 생명·장기손해보험리스크, 일반손해보험리스크, 시장리스크, 신용리스크 및 운영리스크에 대하여 신뢰수준 99.5% 수준에서 충격시나리오 또는 위험계수 방식을 적용하여 충격 후순자산 감소분으로 측정한다.「보험업감독규정」(2025.6.11. 개정)에서는 보험회사의 지급능력과 경영건전성을 확보하기 위해 지급여력비율(K-ICS비율)이 130% 이상을 충족하도록 요구하고 있다.','','ㅈㄱㅇㄹㅂㅇ/ㅂㅇ','{}'::text[]),
(549,'지급준비자산제도','지급준비자산제도란 한국은행이 필요하다고 인정될 때 금융기관에 대하여 예금지급준비금과는 별도의 지급준비자산을 보유할 수 있는 제도(「한국은행법」 제63조)이다.','지급준비자산제도란 한국은행이 필요하다고 인정될 때 금융기관에 대하여 예금지급준비금과는 별도의 지급준비자산을 보유할 수 있는 제도(「한국은행법」 제63조)이다. 지급준비자산에는 현금, 국채, 정부보증채 및 한국은행이 발행하는 통화안정증권 등이 있다. 원래 동 제도는 전통적인 예금지급준비제도를 보완하는 한편 금융기관으로 하여금 국채 등 유가증권을 보유토록 함으로써 국채 등에 대한 수요를 강화시켜 공개시장운영 기반을 마련하기 위해 도입되었다. 통상 지급준비금에 대해서는 이자를 지급하고 있지 않기 때문에 그만큼 기회비용이 발생하게 된다. 그러나 이를 유가증권 등으로 보유하게 되면 수익이 발생함에 따라 지급준비금 보유에 따른 기회비용을 줄일 수 있어 은행의 재무건전성이 제고될 수 있고 지급준비금 보유의무가 없는 비은행금융기관과의 형평성 문제도 줄어들 수있다. 그러나 동 제도는 채권시장의 유통물량을 축소시키는 등 금융시장을 위축시킬 수지니계수있으므로 금융시장 여건을 면밀히 고려하여 시행되어야 한다.','','ㅈㄱㅈㅂㅈㅅㅈㄷ','{}'::text[]),
(550,'지급준비제도','중앙은행이 금융기관으로 하여금 예금 등과 같은 채무의 일정비율에 해당하는 금액을 중앙은행에 예치하도록 하는 제도이다.','중앙은행이 금융기관으로 하여금 예금 등과 같은 채무의 일정비율에 해당하는 금액을 중앙은행에 예치하도록 하는 제도이다. 은행이 예금고객의 지급요구에 응하기 위해 미리 준비해 놓은 유동성 자산을 지급준비금이라 하고, 적립대상 채무 대비 지급준비금의 비율을 지급준비율이라 한다. 지급준비금은 은행이 중앙은행에 예치하고 있는 자금(지준예치금) 과 보유하고 있는 현금(시재금)으로 구성된다. 지급준비제도(Reserve Requirement)는 1863년 미국에서 예금자보호를 위해 법정지급준비금을 부과한 것이 효시라 할 수 있다. 그 후 1930년대 들어 지급준비율을 변경하여 본원통화를 조절하면 승수효과를 통해 통화량에 영향을 준다는 사실이 밝혀지면서 지급준비제도는 중앙은행의 유동성조절수단으로 그 위상이 높아졌다. 그러나 1980년대 이후 금융의 자유화 및 개방화 등으로 시장기능에 바탕을 둔 통화정책의 필요성이 부각되면서 공개시장운영이 주된 통화정책 수단으로 부각된 가운데 지급준비제도는 여러 한계점으로 인해 정책수단으로서의 역할이 상대적으로 축소되었다. 그러나 중앙은행은 지급준비율 변경을 통해 금융기관의 자금사정을 변화시 ㅈ 키고 시중유동성을 조절할 수 있으며 나아가 금융안정을 도모하고 금융시장에 중앙은행의 정책방향을 강력하게 알리는 공시효과가 있기 때문에 지급준비제도는 여전히 유용한 정책수단으로 활용되고 있다.','','ㅈㄱㅈㅂㅈㄷ',ARRAY['통화정책수단']::text[]),
(551,'지니계수','지니계수란 이탈리아의 통계학자 지니(Gini)가 소득분배상태를 파악하기 위하여 로렌츠곡선의 단점을 보완, 로렌츠곡선이 나타내는 내용을 하나의 단순한 숫자로 표시한 것이다.','지니계수란 이탈리아의 통계학자 지니(Gini)가 소득분배상태를 파악하기 위하여 로렌츠곡선의 단점을 보완, 로렌츠곡선이 나타내는 내용을 하나의 단순한 숫자로 표시한 것이다. 소득분배의 불균형 정도가 클수록 소득의 완전균등분배를 나타내는 대각선과 로 렌츠곡선 사이의 면적이 넓어지는 데 착안, 대각선과 로렌츠 곡선 사이의 면적을 대각선에 의해 생성되는 직각삼각형의 면적으로 나눈 값을 계산하여 소득 불평등계수로 사용하였는데, 이를 지니계수라 한다. 소득분배가 완전히 균등할 경우 지니계수는 0이 되며 소득분배가 완전히 불균등할 경우에는 1이 된다. 그러므로 지니계수는 0에서부터 1까지의 값을 가지며 그 값이 클수록 소득분배가 불균등함을 의미한다. 지니계수는 가장 널리쓰이는 소득분배 측정방법이지만 전 계층의 소득분배상태를 하나의 숫자로 나타낼 뿐이 며 특정 소득계층의 소득분포상태를 나타내지 못한다는 한계를 가지고 있다.','','ㅈㄴㄱㅅ',ARRAY['상대적 빈곤율','소득5분위배율']::text[]),
(552,'지로(GIRO)','지로는 대량수납 및 대량지급거래 등 다수인과의 지급거래를 중계센터를 통해 처리하는 소액대량 지급수단중 하나이다.','지로는 대량수납 및 대량지급거래 등 다수인과의 지급거래를 중계센터를 통해 처리하는 소액대량 지급수단중 하나이다. 지로는 지급인이 현금을 입금하거나 지급인의 예금계좌에서 자금이 인출되어 수취인의 계좌로 입금되는 예금계좌이체 방식을 통하여 이루어지기 때문에 시스템 처리구조가 단순하고, 거래상대방을 만날 필요 없이 수취인에게 지급내용(지급인, 지급목적 등)이 통보되므로 격지간 대금결제에 편리하다. 또한 결제금액에 관계없이 건별로 소액의 수수료를 부과하기 때문에 자금이체에 따른 수수료 부담도 적다. 한편 지로업무의 유형은 지로장표의 수반여부에 따라 장표지로업무와 전자지로업무로 구분할 수 있다. 장표지로업무는 지로제도를 이용한 각종 대금의 수납업무가 납부내역이 기재된 지로장표에 의하여 처리되는 업무이며, 전자지로업무에는 각종 대금의 수납 및 지급의뢰시 인터넷 또는 전송파일을 이용하여 전자적으로 처리되는 자동이체, 납부자자동이 체, 대량지급 및 인터넷지로가 있다.','','ㅈㄹ()',ARRAY['입금이체','출금이체']::text[]),
(553,'지방은행공동망','지방은행공동망은 지방은행이 공동으로 운영하는 지급시스템인 뱅크라인(Bankline) 업무를 처리하는 공동망으로서 1997년 6월 가동되었다.','지방은행공동망은 지방은행이 공동으로 운영하는 지급시스템인 뱅크라인(Bankline) 업무를 처리하는 공동망으로서 1997년 6월 가동되었다. 동 시스템의 가동으로 전국적인 영업망을 갖추지 못한 지방은행들도 전국의 고객을 대상으로 예금의 입·출금 및 계좌조회서비스를 제공할 수 있게 되었다. 2017년말 현재 지방은행공동망에는 6개 지방은행이 모두 참여하고 있다. 지방은행공동망의 업무는 입금업무와 출금업무로 구분된다. 입금업무는 타행환공동망과 유사하게 다른 지방은행 계좌로 입금 처리하는 업무이며, 출금업무는 지식서비스 무역통계 CD공동망과 유사한 방식으로 다른 지방은행의 통장을 소지한 고객에게 출금 처리하는 업무이다. 지방은행공동망의 가동시간은 기본적으로 은행 영업시간과 동일한 09시부터 16시까지이며 전산장애 등으로 운영시간 연장이 불가피한 경우에는 금융결제원이 이를 1시간 범위 내에서 연장할 수 있다.','','ㅈㅂㅇㅎㄱㄷㅁ',ARRAY['소액지급시스템']::text[]),
(554,'지분형 모기지','지분형 모기지는 정부나 공공기관이 주택의 일부를 지분으로 투자함으로써 주택 구매자의 자금 부담을 완화해 주는 주택금융 제도이다.','지분형 모기지는 정부나 공공기관이 주택의 일부를 지분으로 투자함으로써 주택 구매자의 자금 부담을 완화해 주는 주택금융 제도이다. 동 제도를 이용할 경우 매수자는 자기자본과 일부 대출만으로 집을 마련할 수 있고, 나머지는 공공기관이 지분을 보유하는 방식으로 부담을 나누게 된다. 예를 들어 10억 원짜리 주택을 구매할 때, 매수자가 1억 원의 자기자본과 4억 원의 대출을 마련하면, 나머지 5억 원은 공공기관이 지분 투자로 참여하게 된다. 이때 등기부에는 공동명의로 등록되며, 매수자는 공공기관의 지분에 대해 낮은 수준의 사용료를 지불한다. 집값이 상승하면 매각 시 시세차익은 지분율에 따라 나뉘 ㅈ 고, 하락 시에는 공공기관이 손실을 먼저 부담하는 구조로 위험 분산 효과도 기대할 수 있다. 또한 매수자는 추후 여유 자금이 생기면 공공 지분을 추가로 매입해 완전한 소유권을 확보할 수도 있다. 동 제도는 청년층과 무주택자의 내 집 마련을 돕고, 가계부채 증가 를 억제하는 정책적 목적도 함께 갖고 있다. 다만 동 제도의 운용에 관한 구체적인 사항은 2025년 7월 현재 확정되지 않았다.','','ㅈㅂㅎㅁㄱㅈ',ARRAY['주택금융제도','한국주택금융공사']::text[]),
(555,'지식서비스 무역통계','지식서비스 무역통계는 국가 간의 지식 기반 서비스 거래 흐름을 계량적으로 측정하고 분석하기 위한 통계로서, 국제수지 통계의 서비스수지에 포함되어 있는 ① 지식재산권 사용료 ② 정보·통신서비스 ③…','지식서비스 무역통계는 국가 간의 지식 기반 서비스 거래 흐름을 계량적으로 측정하고 분석하기 위한 통계로서, 국제수지 통계의 서비스수지에 포함되어 있는 ① 지식재산권 사용료 ② 정보·통신서비스 ③ 문화·여가서비스 ④ 전문·사업서비스 등 4대 지식서비스 분야 를 세분화하여 제공한다. 동 통계는 이들 4대 분야를 16개 세부 유형으로 나누어 산업별 (표준산업분류), 기관형태별(대기업, 중기업, 소기업 등), 거래상대지역별(북미, 아시아, 유럽 등)로 세분화된 수출·수입 및 수지(수출 - 수입) 정보를 보여주며, 표준산업분류상별도 산업분류가 없는 ICT 산업과 콘텐츠 산업에 대해서도 통계를 제공한다.','','ㅈㅅㅅㅂㅅㅁㅇㅌㄱ',ARRAY['국제수지']::text[]),
(556,'지식재산권','지식재산권(Intellectual Property Rights)은 인간의 창의적 활동이나 지식 기반의 산출물에 대해 창작자나 발명가, 개발자 등에게 독점적 사용과 배타적 권리를 부여하는…','지식재산권(Intellectual Property Rights)은 인간의 창의적 활동이나 지식 기반의 산출물에 대해 창작자나 발명가, 개발자 등에게 독점적 사용과 배타적 권리를 부여하는 법적권리이다. 크게 산업재산권과 저작권으로 나뉘며, 산업재산권에는 특허권, 실용신안권, 디자인권, 상표권 등이 포함되고, 저작권은 문학·예술·음악·소프트웨어 등 창작물을 대상으로 한다. 최근에는 영업비밀, 반도체 배치설계, 생명공학적 발명, 데이터베이스 등도 지식재산권의 대상에 포함되고 있다. 과학 기술이 급속히 발달하고 사회에서의 소비 형태도 다양해지면서 새로운 형태의 지식재산권이 나타나고 있으며, 이에 세계 각국은 지식재산권의 보호를 강화하고 있다. 하지만 지식재산권에 대한 기준이 국가마다 일정하지 않고, 특히 개발도상국은 사실상 복제가 방치되고 있다는 점에서 지식재산권에 대한 국가 간 논란이 자주 발생하고 있다.','','ㅈㅅㅈㅅㄱ','{}'::text[]),
(557,'지식재산생산물투자','지식재산생산물투자는 국민계정 체계(SNA; System of National Accounts)에서 건설투자, 설비투자와 함께 총고정자본형성(=투자)을 구성하는 항목이다.','지식재산생산물투자는 국민계정 체계(SNA; System of National Accounts)에서 건설투자, 설비투자와 함께 총고정자본형성(=투자)을 구성하는 항목이다. 여기서 지식재산생산물이란 연구, 개발, 조사, 예술작품 창작 등 지적 노력의 결과물로 이루어진 무형자산을 말한다. 이러한 지식재산생산물투자에는 1년 이상 장기간 동안 생산에 사용될 것으로 예상되는 연구개발(R&D), 오락·문학작품 및 예술품 원본, 컴퓨터 소프트웨어 및 데이터베이스, 광물탐사 등이 있다.','','ㅈㅅㅈㅅㅅㅅㅁㅌㅈ','{}'::text[]),
(558,'지정시점처리제도','실시간 총액결제시스템에서 금융기관의 이체지시는 신청 즉시 처리되는 것이 원칙이나 직불카드어음교환, 타행환 등의 차액결제와 같이 거래 성격상 다수 금융기관 간에 일괄결제가 필요한 거래는 영업시간중…','실시간 총액결제시스템에서 금융기관의 이체지시는 신청 즉시 처리되는 것이 원칙이나 직불카드어음교환, 타행환 등의 차액결제와 같이 거래 성격상 다수 금융기관 간에 일괄결제가 필요한 거래는 영업시간중 특정시점에 처리하고 있는데 이를 지정시점처리제도라 한다. 자금의 이체지시를 영업시간 중에 건별로 실시간 처리하는 실시간총액결제방식에 대응하는 개념이다. 지정시점처리제도는 다수의 참가기관이 서로 연결되는 대량의 거래를 특정시점에서 일괄적으로 처리함으로써 참가기관들이 예측가능하고 효율적인 자금관리를 할수 있고 결제에 필요한 유동성을 절약할 수 있는 장점이 있는 반면 지정시점에 모든 참가 기관이 결제를 이행한다는 보장이 없어 별도의 결제리스크 관리방안이 구비되어야 한다. 현재 한은금융망에서는 11시(금융기관 간 차액결제가 이루어지는 타행환, CD공동망, 은 행지로, 직불카드, CMS, 지방은행공동망, 전자금융공동망, 어음교환 등), 11시 5분(1일물콜자금 상환), 14시(국고금 수납자금 회수) 등의 지정처리시점을 설정·운영하고 있다.','','ㅈㅈㅅㅈㅊㄹㅈㄷ',ARRAY['차액결제시스템']::text[]),
(559,'지주회사','지주회사는 다른 회사의 주식을 소유하여 그 회사의 사업내용을 지배하는 것을 주된 사업 ㅈ 으로 하는 회사이다.','지주회사는 다른 회사의 주식을 소유하여 그 회사의 사업내용을 지배하는 것을 주된 사업 ㅈ 으로 하는 회사이다. 공정거래법에서는 다른 회사의 사업내용을 지배할 목적으로 소유하는 주식의 대차대조표상 장부가액의 합계액이 당해 회사 자산총액의 50% 이상인 회사를 지주회사로 규정하고 있다. 지주회사는 지주회사가 사업을 영위하는가의 여부에 따라 순수지주회사와 사업지주회사로 구분된다. 순수지주회사는 다른 기업의 사업내용 지배만을 목적으로 하는 지주회사를 말하고 사업지주회사는 자기사업을 영위하면서 다른 기업의 사업내용을 지배하는 지주회사를 말한다.','','ㅈㅈㅎㅅ',ARRAY['M&A']::text[]),
(560,'직불카드','직불카드(Debit Card)는 카드소지인(고객)이 물품이나 서비스를 구매하는 경우 동 카드를 이용하여 판매점에 설치되어 있는 단말기와 카드 발급은행의 주전산기를 통하여 고객의 예금계좌에서…','직불카드(Debit Card)는 카드소지인(고객)이 물품이나 서비스를 구매하는 경우 동 카드를 이용하여 판매점에 설치되어 있는 단말기와 카드 발급은행의 주전산기를 통하여 고객의 예금계좌에서 구매대금을 인출하고 이를 판매자의 예금계좌로 자동이체해 주는 용도 로 사용되는 카드이다. 직불카드는 백화점, 슈퍼마켓 등 판매점에서 물품판매와 동시에 고객의 계좌에서 대금이 출금되어 현금을 지급하는 것과 동일한 효과가 있으므로 EFT/ POS (Electronic Funds Transfer at the Point of Sales)카드라고도 부른다. 우리나라에 서는 1996년 2월부터 본격 가동되기 시작한 직불카드공동망을 통하여 서비스가 제공되고 있다.','','ㅈㅂㅋㄷ',ARRAY['지급수단','직불카드공동망']::text[]);
